INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('onejs/one/railway', 'railway', 'onejs', 'one', 'community', 'railway onejs one community Railway是一个新的React框架，允许开发者使用单一的Vite插件和共享代码来构建跨平台应用 Railwayは新しいReactフレームワークで、シングルプラグインと共有コードでクロスプラットフォーム開発が可能 Railway는 리액트 프레임워크로 싱글 플러그인과 공유 코드를 사용하여 웹과 네이티브 애플리케이션을 개발할 수 있습니다 Railway es un framework React que permite desarrollar aplicaciones web y nativas con un solo plugin Vite y código compartido, facilitando la creación de aplicaciones cross-plataforma Railway est un framework React qui permet de développer des applications web et natives avec un seul plugin Vite et code partagé, facilitant la création d''applications cross-plateforme Railway ist ein React-Framework, das die Entwicklung von Web- und Native-Anwendungen mit einem einzigen Vite-Plugin und gemeinsamem Code ermöglicht, was die Erstellung von Cross-Plattform-Anwendungen erleichtert Railway é um novo framework React que permite desenvolver aplicativos web e nativos com um único plugin Vite e código compartilhado. Railway - новый фреймворк React, который позволяет разрабатывать веб- и мобильные приложения с одним плагином Vite и общим кодом. Railway هو إطار React جديد يسمح بالتطوير التطبيقات الويب والأصلية مع إضافة Vite واحدة ورمز مشترك. ❶ One is a new React framework - target web and native with a single Vite plugin and fully shared code, so you can ship cross-platform nearly as easy as single-platform. Railway AIエージェント React框架 跨平台开发 Vite插件 共享代码 如何使用Railway Railway替代品 Railway教程 Railway安装 ❶ One is a new React framework - target web and native with a single Vite plugin and fully shared code, so you can ship cross-platform nearly as easy as single-platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ace-step/ACE-Step-1.5/acestep-docs', 'community', 'ace-step', 'ACE-Step-1.5', 'ace-step/ACE-Step-1.5', 'acestep-docs', 0, 0, 44, '2026-03-04T13:07:01.692Z', '2026-03-04T13:35:00.391Z', '32f02c5a183ae7026c1e3adc85604589d2b1430ebd799d554fb07be9dc0f3356', '{"id":"ace-step/ACE-Step-1.5/acestep-docs","name":"acestep-docs","description":{"zh":"acestep-docs是一个强大的本地音乐生成模型，支持多种设备，包括Mac、AMD、Intel和CUDA设备","ja":"acestep-docsはローカル音楽生成モデルで、Mac、AMD、Intel、CUDAデバイスをサポートします","ko":"acestep-docs는 로컬 음악 생성 모델로 Mac, AMD, Intel, CUDA 장치를 지원합니다","es":"acestep-docs es un modelo de generación de música local que supera a la mayoría de las alternativas comerciales, compatible con dispositivos Mac, AMD, Intel y CUDA","fr":"acestep-docs est un modèle de génération de musique locale qui surpasse la plupart des alternatives commerciales, compatible avec les appareils Mac, AMD, Intel et CUDA","de":"acestep-docs ist ein lokales Musikgenerierungsmodell, das die meisten kommerziellen Alternativen übertrifft, kompatibel mit Geräten von Mac, AMD, Intel und CUDA","pt":"O acestep-docs é uma ferramenta de IA poderosa para geração de música local que suporta Mac, AMD, Intel e dispositivos CUDA, superando alternativas comerciais.","ru":"ИИ Агент acestep-docs - это мощная локальная модель генерации музыки, поддерживающая Mac, AMD, Intel и устройства CUDA, которая превосходит коммерческие альтернативы.","ar":"أداة الذكاء الاصطناعي acestep-docs هي نموذج توليد موسيقي محلي قوي يدعم ماك، إيه إم دي، إنتل وأجهزة كيودا، ويتفوق على البديلات التجارية.","en":"The most powerful local music generation model that outperforms most commercial alternatives, supporting Mac, AMD, Intel, and CUDA devices."},"seo":{"title":{"zh":"AI工具：acestep-docs本地音乐生成模型","ja":"AIエージェント：acestep-docsローカル音楽生成モデル","ko":"AI 에이전트: acestep-docs 로컬 음악 생성 모델","es":"Herramientas de IA: acestep