INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('christopher-buss/rbxts-jest-extended/isentinel', 'isentinel', 'christopher-buss', 'rbxts-jest-extended', 'community', 'isentinel christopher-buss rbxts-jest-extended community isentinel是基于rbxts的Jest扩展，提供额外的匹配器 isentinelはrbxts用のJestマッチャーを提供するエージェントです isentinel은 rbxts용 Jest 매처를 제공하는 에이전트입니다 Isentinel es una herramienta de AI que proporciona matchers adicionales para Jest en rbxts, mejorando la eficiencia de las pruebas Isentinel est un outil d''IA qui propose des matchers supplémentaires pour Jest en rbxts, améliorant l''efficacité des tests Isentinel ist ein KI-Tool, das zusätzliche Matcher für Jest in rbxts bietet, die Effizienz der Tests verbessert O isentinel é uma ferramenta de AI que fornece recursos adicionais para Jest, melhorando a experiência de desenvolvimento para rbxts ИИ Агент isentinel предоставляет дополнительные матчеры для Jest, улучшая опыт разработки для rbxts أداة إصطناعي isentinel توفر ميزات إضافية لJest، وتحسن من تجربة التطوير لrbxts Additional Jest matchers for rbxts🃏💪 (Sourced from https://github.com/jest-community/jest-extended) AI智能工具 Jest扩展 rbxts 测试效率 如何使用isentinel isentinel安装 Jest匹配器 Additional Jest matchers for rbxts🃏💪 (Sourced from https://github.com/jest-community/jest-extended)');
