INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ilenburg1993/chatgpt-docker-puppeteer/rag-mcp-lsp-ops', 'rag-mcp-lsp-ops', 'Ilenburg1993', 'chatgpt-docker-puppeteer', 'community', 'rag-mcp-lsp-ops Ilenburg1993 chatgpt-docker-puppeteer community rag-mcp-lsp-ops是一个基于Puppeteer的自主AI代理，用于浏览器自动化，具有域驱动任务处理、自适应验证和实时监控功能 rag-mcp-lsp-opsはPuppeteerを基盤とする自律型AIエージェントであり、ブラウザ自動化を実現し、ドメイン駆動タスク処理、適応型バリデーション、リアルタイムモニタリング機能を備えている rag-mcp-lsp-ops는 Puppeteer 기반의 자율형 AI 에이전트로서 브라우저 자동화를 구현하고 도메인 주도 작업 처리, 적응형 검증, 실시간 모니터링 기능을 제공 El agente AI rag-mcp-lsp-ops es un sistema de automatización de navegador con Puppeteer que ofrece procesamiento de tareas con validación adaptativa y monitoreo en tiempo real L''agent IA rag-mcp-lsp-ops est un système d''automatisation de navigateur avec Puppeteer qui propose un traitement de tâches avec validation adaptative et surveillance en temps réel Der KI-Agent rag-mcp-lsp-ops ist ein System für die Browser-Automatisierung mit Puppeteer, das eine Aufgabenverarbeitung mit adaptiver Validierung und Echtzeit-Überwachung bietet O rag-mcp-lsp-ops é um agente AI autônomo para automação de navegador com Puppeteer, processamento de tarefas orientado a domínio e validação adaptativa ИИ агент rag-mcp-lsp-ops для автоматизации браузера с Puppeteer, доменно-ориентированной обработки задач и адаптивной валидации وكيل الذكاء الاصطناعي rag-mcp-lsp-ops للتحكم في المتصفح مع Puppeteer وعمليات المهام الموجهة بالمحتوى والتحقق التكيفي 🤖 Autonomous AI agent for browser automation with Puppeteer - Domain-driven task processing with adaptive validation and real-time monitoring AI智能代理 浏览器自动化 Puppeteer 如何使用rag-mcp-lsp-ops rag-mcp-lsp-ops安装 rag-mcp-lsp-ops设置指南 浏览器自动化工具 AI工具 🤖 Autonomous AI agent for browser automation with Puppeteer - Domain-driven task processing with adaptive validation and real-time monitoring');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('f/prompts.chat/widget-generator', 'community', 'f', 'prompts.chat', 'f/prompts.chat', 'widget-generator', 149619, 19672, 43, '2026-03-02T13:04:57Z', '2026-03-02T13:14:21.999Z', 'efc37f2fc7345b6a79558613f4ead2c44df8a13525cb8d7bc69a332d9241b442', '{"id":"f/prompts.chat/widget-generator","name":"widget-generator","description":{"zh":"Widget_generator是一个免费、开源的AI智能工具，用于分享和发现社区驱动的ChatGPT提示","ja":"Widget_generatorは、コミュニティドリブンのChatGPTプロンプトを共有、発見するための無料、オープンソースのAIエージェントです","ko":"Widget_generator는 커뮤니티 주도형 ChatGPT 프롬프트를 공유하고 발견하기 위한 무료 오픈소스 AI 에이전트입니다","es":"El generador de widgets es una herramienta de código abierto que permite compartir y descubrir prompts de la comunidad.","fr":"Le générateur de widgets est un outil open source qui permet de partager et de découvrir des prompts de la communauté.","de":"Der KI-Widget-Generator ist ein Open-Source-Tool, das das Teilen und Entdecken von Community-Prompts ermöglicht.","pt":"O widget-generator é uma ferramenta de código aberto para compartilhar e descobrir prompts de IA.","ru":"ИИ Агенты: Генератор Виджетов - это открытый исходный код для обмена и открытия промптов ИИ.","ar":"مولد أدوات ذكاء اصطناعي هو أداة مفتوحة المصدر لمشاركة واستكشاف محفزات الذكاء الاصطناعي.","en":"f.k.a. Awesome ChatGPT Prompts. Share, discover, and collect prompts from the community. Free and open source — self-host for your organization with complete privacy."},"seo":{"title":{"zh":"AI智能工具Widget_generator","ja":"AIエージェントWidget_generator","ko":"AI 에이전트 Widget_generator","es":"Generador de widgets de inteligencia artificial","fr":"Générateur de widgets d''agents IA","de":"KI-Widget-Generator","pt":"Gerador de Widgets de IA - Ferramentas de Inteligência Ar...","ru":"ИИ Агенты: Генератор Виджетов - Инструменты Искусственног...","ar":"مولد أدوات ذكاء اصطناعي - أدوات ذكاء اصطناعي","en":"widget-generator"},"description":{"zh":"Widget_generator是一个免费、开源的AI智能工具，用于分享和发现社区驱动的ChatGPT提示","ja":"Widget_generatorは、コミュニティドリブンのChatGPTプロンプトを共有、発見するための無料、オープンソースのAIエージェントです","ko":"Widget_generator는 커뮤니티 주도형 ChatGPT 프롬프트를 공유하고 발견하기 위한 무료 오픈소스 AI 에이전트입니다","es":"El generador de widgets es una herramienta de código abierto que permite compartir y descubrir prompts de la comunidad.","fr":"Le générateur de widgets est un outil open source qui permet de partager et de découvrir des prompts de la communauté.","de":"Der KI-Widget-Generator ist ein Open-Source-Tool, das das Teilen und Entdecken von Community-Prompts ermöglicht.","pt":"O widget-generator é uma ferramenta de código aberto para compartilhar e descobrir prompts de IA.","ru":"ИИ Агенты: Генератор Виджетов - это открытый исходный код для обмена и открытия промптов ИИ.","ar":"مولد أدوات ذكاء اصطناعي هو أداة مفتوحة المصدر لمشاركة واستكشاف محفزات الذكاء الاصطناعي.","en":"f.k.a. Awesome ChatGPT Prompts. Share, discover, and collect prompts from the community. Free and open source — self-host for your organization with complete..."},"definition":{"en":"f.k.a. Awesome ChatGPT Prompts. Share, discover, and collect prompts from the community. Free and open source — self-host for your organization with complete privacy."},"features":{"zh":["免费、开源","社区驱动的ChatGPT提示","支持自托管","使用Next.js和TypeScript构建"],"ja":["無料、オープンソース","コミュニティドリブンのChatGPTプロンプト","セルフホスティングに対応","Next.jsとTypeScriptで構築"],"ko":["무료, 오픈소스","커뮤니티 주도형 ChatGPT 프롬프트","셀프 호스팅 지원","Next.js와 TypeScript로 구축"],"es":["Código abierto y autohospedado","Compartir y descubrir prompts de la comunidad","Interfaz de usuario personalizable","Compatible con ChatGPT y otros agentes de IA","Desarrollado con Next.js y TypeScript"],"fr":["Code ouvert et auto-hébergé","Partager et découvrir des prompts de la communauté","Interface utilisateur personnalisable","Compatible avec ChatGPT et d''autres agents IA","Développé avec Next.js et TypeScript"],"de":["Open-Source- und selbstgehostet","Teilen und entdecken von Community-Prompts","Benutzerdefinierte Benutzeroberfläche","Kompatibel mit ChatGPT und anderen KI-Agents","Entwickelt mit Next.js und TypeScript"],"pt":["Compartilhe prompts de IA com a comunidade","Descubra novos prompts de IA","Código aberto para sua organização","Privacidade completa","Integração com ChatGPT e outros modelos de IA"],"ru":["Обменяйтесь промптами ИИ с сообществом","Откройте для себя новые промпты ИИ","Открытый исходный код для вашей организации","Полная приватность","Интеграция с ChatGPT и другими моделями ИИ"],"ar":["شارك محفزات الذكاء الاصطناعي مع المجتمع","اكتشف محفزات الذكاء الاصطناعي الجديدة","أداة مفتوحة المصدر لمنظمتك","الخصوصية الكاملة","التكامل مع ChatGPT و نماذج الذكاء الاصطناعي الأخرى"]},"keywords":{"zh":["如何使用Widget_generator","什么是ChatGPT提示","Widget_generator替代品","Widget_generator vs ChatGPT","Widget_generator安装","Widget_generator设置指南","AI智能工具","开源AI工具"],"ja":["Widget_generatorの使い方","ChatGPTプロンプトとは","Widget_generatorの代替","Widget_generator vs ChatGPT","Widget_generatorのインストール","Widget_generatorの設定ガイド","AIエージェント","オープンソースAIエージェント"],"ko":["Widget_generator 사용법","ChatGPT 프롬프트란","Widget_generator 대안","Widget_generator vs ChatGPT","Widget_generator 설치","Widget_generator 설정 가이드","AI 에이전트","오픈소스 AI 에이전트"],"es":["cómo usar el generador de widgets de IA","qué es un agente de inteligencia artificial","alternativas al generador de widgets de IA","generador de widgets de IA vs ChatGPT","instalación del generador de widgets de IA","guía de configuración del generador de widgets de IA"],"fr":["comment utiliser le générateur de widgets d''agents IA","qu''est-ce qu''un agent d''intelligence artificielle","alternatives au générateur de widgets d''agents IA","générateur de widgets d''agents IA vs ChatGPT","installation du générateur de widgets d''agents IA","guide de configuration du générateur de widgets d''agents IA"],"de":["wie man den KI-Widget-Generator verwendet","was ist ein KI-Agents","Alternativen zum KI-Widget-Generator","KI-Widget-Generator vs ChatGPT","Installation des KI-Widget-Generators","Konfigurationsanleitung für den KI-Widget-Generator"],"pt":["como usar widget-generator","o que é widget-generator","widget-generator alternativa","widget-generator vs ChatGPT","instalar widget-generator","guia de configuração do widget-generator","ferramentas de inteligência artificial","desenvolvimento de IA"],"ru":["как использовать ИИ Агенты","что такое ИИ Агенты","ИИ Агенты альтернатива","ИИ Агенты vs ChatGPT","установить ИИ Агенты","руководство по настройке ИИ Агентов","инструменты искусственного интеллекта","разработка ИИ"],"ar":["كيفية استخدام مولد أدوات ذكاء اصطناعي","ما هو مولد أدوات ذكاء اصطناعي","بديل مولد أدوات ذكاء اصطناعي","مولد أدوات ذكاء اصطناعي مقابل ChatGPT","تثبيت مولد أدوات ذكاء اصطناعي","دليل إعداد مولد أدوات ذكاء اصطناعي","أدوات الذكاء الاصطناعي","تطوير الذكاء الاصطناعي"]}},"owner":"f","repo":"prompts.chat","repoPath":"f/prompts.chat","stars":149619,"forks":19672,"updatedAt":"2026-03-02T13:04:57Z","topics":["ai","artificial-intelligence","awesome-list","chatgpt","chatgpt-prompts","claude","gemini","gpt","gpt-4","llm","machine-learning","nextjs","open-source","openai","prompt-engineering","prompts","prompts-chat","typescript"],"category":"community","skillMd":{"name":"widget-generator","description":"Generate customizable widget plugins for the prompts.chat feed system","bodyPreview":"# Widget Generator Skill\n\nThis skill guides creation of widget plugins for **prompts.chat**. Widgets are injected into prompt feeds to display promotional content, sponsor cards, or custom interactive components.\n\n## Overview\n\nWidgets support two rendering modes:\n1. **Standard prompt widget** - Uses default `PromptCard` styling (like `coderabbit.ts`)\n2. **Custom render widget** - Full custom React component (like `book.tsx`)\n\n## Prerequisites\n\nBefore creating a widget, gather from the user:\n\n| P","body":"# Widget Generator Skill\n\nThis skill guides creation of widget plugins for **prompts.chat**. Widgets are injected into prompt feeds to display promotional content, sponsor cards, or custom interactive components.\n\n## Overview\n\nWidgets support two rendering modes:\n1. **Standard prompt widget** - Uses default `PromptCard` styling (like `coderabbit.ts`)\n2. **Custom render widget** - Full custom React component (like `book.tsx`)\n\n## Prerequisites\n\nBefore creating a widget, gather from the user:\n\n| Parameter | Required | Description |\n|-----------|----------|-------------|\n| Widget ID | ✅ | Unique identifier (kebab-case, e.g., `my-sponsor`) |\n| Widget Name | ✅ | Display name for the plugin |\n| Rendering Mode | ✅ | `standard` or `custom` |\n| Sponsor Info | ❌ | Name, logo, logoDark, URL (for sponsored widgets) |\n\n## Step 1: Gather Widget Configuration\n\nAsk the user for the following configuration options:\n\n### Basic Info\n```\n- id: string (unique, kebab-case)\n- name: string (display name)\n- slug: string (URL-friendly identifier)\n- title: string (card title)\n- description: string (card description)\n```\n\n### Content (for standard mode)\n```\n- content: string (prompt content, can be multi-line markdown)\n- type: \"TEXT\" | \"STRUCTURED\"\n- structuredFormat?: \"json\" | \"yaml\" (if type is STRUCTURED)\n```\n\n### Categorization\n```\n- tags?: string[] (e.g., [\"AI\", \"Development\"])\n- category?: string (e.g., \"Development\", \"Writing\")\n```\n\n### Action Button\n```\n- actionUrl?: string (CTA link)\n- actionLabel?: string (CTA button text)\n```\n\n### Sponsor (optional)\n```\n- sponsor?: {\n    name: string\n    logo: string (path to light mode logo)\n    logoDark?: string (path to dark mode logo)\n    url: string (sponsor website)\n  }\n```\n\n### Positioning Strategy\n```\n- positioning: {\n    position: number (0-indexed start position, default: 2)\n    mode: \"once\" | \"repeat\" (default: \"once\")\n    repeatEvery?: number (for repeat mode, e.g., 30)\n    maxCount?: number (max occurrences, default: 1 for once, unlimited for repeat)\n  }\n```\n\n### Injection Logic\n```\n- shouldInject?: (context) => boolean\n  Context contains:\n  - filters.q: search query\n  - filters.category: category name\n  - filters.categorySlug: category slug\n  - filters.tag: tag filter\n  - filters.sort: sort option\n  - itemCount: total items in feed\n```\n\n## Step 2: Create Widget File\n\n### Standard Widget (TypeScript only)\n\nCreate file: `src/lib/plugins/widgets/{widget-id}.ts`\n\n```typescript\nimport type { WidgetPlugin } from \"./types\";\n\nexport const {widgetId}Widget: WidgetPlugin = {\n  id: \"{widget-id}\",\n  name: \"{Widget Name}\",\n  prompts: [\n    {\n      id: \"{prompt-id}\",\n      slug: \"{prompt-slug}\",\n      title: \"{Title}\",\n      description: \"{Description}\",\n      content: `{Multi-line content here}`,\n      type: \"TEXT\",\n      // Optional sponsor\n      sponsor: {\n        name: \"{Sponsor Name}\",\n        logo: \"/sponsors/{sponsor}.svg\",\n        logoDark: \"/sponsors/{sponsor}-dark.svg\",\n        url: \"{sponsor-url}\",\n      },\n      tags: [\"{Tag1}\", \"{Tag2}\"],\n      category: \"{Category}\",\n      actionUrl: \"{action-url}\",\n      actionLabel: \"{Action Label}\",\n      positioning: {\n        position: 2,\n        mode: \"repeat\",\n        repeatEvery: 50,\n        maxCount: 3,\n      },\n      shouldInject: (context) => {\n        const { filters } = context;\n        \n        // Always show when no filters active\n        if (!filters?.q && !filters?.category && !filters?.tag) {\n          return true;\n        }\n        \n        // Add custom filter logic here\n        return false;\n      },\n    },\n  ],\n};\n```\n\n### Custom Render Widget (TSX with React)\n\nCreate file: `src/lib/plugins/widgets/{widget-id}.tsx`\n\n```tsx\nimport Link from \"next/link\";\nimport Image from \"next/image\";\nimport { Button } from \"@/components/ui/button\";\nimport type { WidgetPlugin } from \"./types\";\n\nfunction {WidgetName}Widget() {\n  return (\n    <div className=\"group border rounded-[var(--radius)] overflow-hidden hover:border-foreground/20 transition-colors bg-gradient-to-br from-primary/5 via-background to-primary/10 p-5\">\n      {/* Custom widget content */}\n      <div className=\"flex flex-col items-center gap-4\">\n        {/* Image/visual element */}\n        <div className=\"relative w-full aspect-video\">\n          <Image\n            src=\"/path/to/image.jpg\"\n            alt=\"{Alt text}\"\n            fill\n            className=\"object-cover rounded-lg\"\n          />\n        </div>\n        \n        {/* Content */}\n        <div className=\"w-full text-center\">\n          <h3 className=\"font-semibold text-base mb-1.5\">{Title}</h3>\n          <p className=\"text-xs text-muted-foreground mb-4\">{Description}</p>\n          <Button asChild size=\"sm\" className=\"w-full\">\n            <Link href=\"{action-url}\">{Action Label}</Link>\n          </Button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport const {widgetId}Widget: WidgetPlugin = {\n  id: \"{widget-id}\",\n  name: \"{Widget Name}\",\n  prompts: [\n    {\n      id: \"{prompt-id}\",\n      slug: \"{prompt-slug}\",\n      title: \"{Title}\",\n      description: \"{Description}\",\n      content: \"\",\n      type: \"TEXT\",\n      tags: [\"{Tag1}\", \"{Tag2}\"],\n      category: \"{Category}\",\n      actionUrl: \"{action-url}\",\n      actionLabel: \"{Action Label}\",\n      positioning: {\n        position: 10,\n        mode: \"repeat\",\n        repeatEvery: 60,\n        maxCount: 4,\n      },\n      shouldInject: () => true,\n      render: () => <{WidgetName}Widget />,\n    },\n  ],\n};\n```\n\n## Step 3: Register Widget\n\nEdit `src/lib/plugins/widgets/index.ts`:\n\n1. Add import at top:\n```typescript\nimport { {widgetId}Widget } from \"./{widget-id}\";\n```\n\n2. Add to `widgetPlugins` array:\n```typescript\nconst widgetPlugins: WidgetPlugin[] = [\n  coderabbitWidget,\n  bookWidget,\n  {widgetId}Widget, // Add new widget\n];\n```\n\n## Step 4: Add Sponsor Assets (if applicable)\n\nIf the widget has a sponsor:\n1. Add light logo: `public/sponsors/{sponsor}.svg`\n2. Add dark logo (optional): `public/sponsors/{sponsor}-dark.svg`\n\n## Positioning Examples\n\n### Show once at position 5\n```typescript\npositioning: {\n  position: 5,\n  mode: \"once\",\n}\n```\n\n### Repeat every 30 items, max 5 times\n```typescript\npositioning: {\n  position: 3,\n  mode: \"repeat\",\n  repeatEvery: 30,\n  maxCount: 5,\n}\n```\n\n### Unlimited repeating\n```typescript\npositioning: {\n  position: 2,\n  mode: \"repeat\",\n  repeatEvery: 25,\n  // No maxCount = unlimited\n}\n```\n\n## shouldInject Examples\n\n### Always show\n```typescript\nshouldInject: () => true,\n```\n\n### Only when no filters active\n```typescript\nshouldInject: (context) => {\n  const { filters } = context;\n  return !filters?.q && !filters?.category && !filters?.tag;\n},\n```\n\n### Show for specific categories\n```typescript\nshouldInject: (context) => {\n  const slug = context.filters?.categorySlug?.toLowerCase();\n  return slug?.includes(\"development\") || slug?.includes(\"coding\");\n},\n```\n\n### Show when search matches keywords\n```typescript\nshouldInject: (context) => {\n  const query = context.filters?.q?.toLowerCase() || \"\";\n  return [\"ai\", \"automation\", \"workflow\"].some(kw => query.includes(kw));\n},\n```\n\n### Show only when enough items\n```typescript\nshouldInject: (context) => {\n  return (context.itemCount ?? 0) >= 10;\n},\n```\n\n## Custom Render Patterns\n\n### Card with gradient background\n```tsx\n<div className=\"border rounded-[var(--radius)] overflow-hidden bg-gradient-to-br from-primary/5 via-background to-primary/10 p-5\">\n```\n\n### Sponsor badge\n```tsx\n<div className=\"flex items-center gap-2 mb-2\">\n  <span className=\"text-xs font-medium text-primary\">Sponsored</span>\n</div>\n```\n\n### Responsive image\n```tsx\n<div className=\"relative w-full aspect-video\">\n  <Image src=\"/image.jpg\" alt=\"...\" fill className=\"object-cover\" />\n</div>\n```\n\n### CTA button\n```tsx\n<Button asChild size=\"sm\" className=\"w-full\">\n  <Link href=\"https://example.com\">\n    Learn More\n    <ArrowRight className=\"ml-2 h-3.5 w-3.5\" />\n  </Link>\n</Button>\n```\n\n## Verification\n\n1. Run type check:\n   ```bash\n   npx tsc --noEmit\n   ```\n\n2. Start dev server:\n   ```bash\n   npm run dev\n   ```\n\n3. Navigate to `/discover` or `/feed` to verify widget appears at configured positions\n\n## Type Reference\n\n```typescript\ninterface WidgetPrompt {\n  id: string;\n  slug: string;\n  title: string;\n  description: string;\n  content: string;\n  type: \"TEXT\" | \"STRUCTURED\";\n  structuredFormat?: \"json\" | \"yaml\";\n  sponsor?: {\n    name: string;\n    logo: string;\n    logoDark?: string;\n    url: string;\n  };\n  tags?: string[];\n  category?: string;\n  actionUrl?: string;\n  actionLabel?: string;\n  positioning?: {\n    position?: number;      // Default: 2\n    mode?: \"once\" | \"repeat\"; // Default: \"once\"\n    repeatEvery?: number;   // For repeat mode\n    maxCount?: number;      // Max occurrences\n  };\n  shouldInject?: (context: WidgetContext) => boolean;\n  render?: () => ReactNode; // For custom rendering\n}\n\ninterface WidgetPlugin {\n  id: string;\n  name: string;\n  prompts: WidgetPrompt[];\n}\n```\n\n## Common Issues\n\n| Issue | Solution |\n|-------|----------|\n| Widget not showing | Check `shouldInject` logic, verify registration in `index.ts` |\n| TypeScript errors | Ensure imports from `./types`, check sponsor object shape |\n| Styling issues | Use Tailwind classes, match existing widget patterns |\n| Position wrong | Remember positions are 0-indexed, check `repeatEvery` value |\n"},"lastSynced":"2026-03-02T13:14:21.999Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in React and custom UI component development, seeking to inject interactive widgets into prompt feeds.","zh":"适合专门从事React和自定义UI组件开发的前端代理，希望将交互式小部件注入到提示提要中。","ja":"ReactやカスタムUIコンポーネント開発を専門とするフロントエンドエージェントに適しています。プロンプトフィードにインタラクティブウィジェットを注入することを目指します。","ko":"React 및 사용자 지정 UI 구성 요소 개발을 전문으로 하는 프런트엔드 에이전트에게 적합합니다. 프롬프트 피드에 상호 작용 위젯을 삽입하려는 경우에 사용됩니다.","es":"Ideal para agentes de frontend que se especializan en React y desarrollo de componentes de interfaz de usuario personalizados, que buscan inyectar widgets interactivos en feeds de prompts.","fr":"Idéal pour les agents de frontend spécialisés dans React et le développement de composants d''interface utilisateur personnalisés, souhaitant injecter des widgets interactifs dans les flux de invites.","de":"Ideal für Frontend-Agenten, die sich auf React und die Entwicklung von benutzerdefinierten Benutzeroberflächenkomponenten spezialisieren und interaktive Widgets in Prompt-Feeds einfügen möchten.","pt":"Ideal para Agentes Frontend especializados em React e desenvolvimento de componentes de UI personalizados, buscando injetar widgets interativos em feeds de prompt.","ru":"Идеально для агентов Frontend, специализирующихся на React и разработке пользовательских компонентов UI, стремящихся внедрять интерактивные виджеты в потоки подсказок.","ar":"مثالي لوكلاء واجهة المستخدم الأمامية المتخصصين في React وتطوير مكونات واجهة المستخدم المخصصة ،寻求 حقن أدوات تفاعلية في تدفقات التلميح."},"recommendation":{"en":"Empowers agents to create custom React components for promotional content, sponsor cards, or interactive elements, utilizing standard prompt widget and custom render widget modes, with support for React-based rendering and customization.","zh":"赋予代理创建自定义React组件以用于促销内容、赞助卡或交互元素的能力，利用标准提示小部件和自定义渲染小部件模式，并支持基于React的渲染和自定义。","ja":"プロモーションコンテンツ、スポンサーカード、またはインタラクティブ要素のために、標準のプロンプトウィジェットとカスタムレンダウィジェットモードを使用し、ReactベースのレンダリングとカスタマイズをサポートするカスタムReactコンポーネントを作成するエージェントの能力を提供します。","ko":"표준 프로ンプ트 위젯 및 사용자 지정 렌더링 위젯 모드를 사용하여 프로모션 콘텐츠, 스폰서 카드 또는 상호 작용 요소를 위한 사용자 지정 React 구성 요소를 생성할 수 있는 에이전트의 능력을 제공하며 React 기반 렌더링 및 사용자 지정도 지원합니다.","es":"Permite a los agentes crear componentes personalizados de React para contenido promocional, tarjetas de patrocinio o elementos interactivos, utilizando los modos de widget de prompt estándar y personalizado, con soporte para renderizado y personalización basados en React.","fr":"Permet aux agents de créer des composants React personnalisés pour du contenu promotionnel, des cartes de parrainage ou des éléments interactifs, en utilisant les modes de widget de invite standard et personnalisé, avec une prise en charge du rendu et de la personnalisation basés sur React.","de":"Ermöglicht es Agenten, benutzerdefinierte React-Komponenten für Werbeinhalte, Sponsorenkarten oder interaktive Elemente zu erstellen, indem sie die Standard-Prompt-Widget- und benutzerdefinierten Render-Widget-Modi verwenden, mit Unterstützung für React-basiertes Rendering und Anpassung.","pt":"Habilita os agentes a criar componentes personalizados do React para conteúdo promocional, cartões de patrocinador ou elementos interativos, utilizando modos de widget de prompt padrão e personalizado e renderização baseada em React e personalização.","ru":"Предоставляет агентам возможность создавать пользовательские компоненты React для промо-контента, спонсорских карточек или интерактивных элементов, используя стандартные режимы виджетов подсказок и пользовательскую отрисовку, с поддержкой рендеринга и настройки на основе React.","ar":"يتمكن الوكلاء من إنشاء مكونات React المخصصة للمحتوى الترويجي أو بطاقات الرعاة أو العناصر التفاعلية ، باستخدام أوضاع Widget التلميح القياسية والمخصصة وطريقة عرض React والتخصيص."},"useCases":{"en":["Injecting promotional content into prompt feeds using standard prompt widgets","Creating custom interactive components with full React component customization","Developing sponsor cards with tailored styling and functionality"],"zh":["使用标准提示小部件将促销内容注入到提示提要中","使用完整的React组件自定义创建自定义交互组件","开发具有定制样式和功能的赞助卡"],"ja":["標準プロンプトウィジェットを使用してプロモーションコンテンツをプロンプトフィードに注入する","フルReactコンポーネントカスタマイズを使用してカスタムインタラクティブコンポーネントを作成する","カスタムスタイリングと機能を備えたスポンサーカードを開発する"],"ko":["표준 프로ンプ트 위젯을 사용하여 프로모션 콘텐츠를 프로ンプ트 피드에 삽입하는 경우","전체 React 구성 요소 사용자 지정으로 사용자 지정 상호 작용 구성 요소를 만드는 경우","사용자 지정 스타일 및 기능이 포함된 스폰서 카드를 개발하는 경우"],"es":["Inyectar contenido promocional en feeds de prompts utilizando widgets de prompt estándar","Crear componentes interactivos personalizados con personalización completa de componentes de React","Desarrollar tarjetas de patrocinio con estilos y funcionalidades personalizados"],"fr":["Injecter du contenu promotionnel dans les flux de invites à l''aide de widgets de invite standard","Créer des composants interactifs personnalisés avec une personnalisation complète des composants React","Développer des cartes de parrainage avec des styles et des fonctionnalités personnalisés"],"de":["Werbeinhalte in Prompt-Feeds mit Standard-Prompt-Widgets einfügen","Benutzerdefinierte interaktive Komponenten mit vollständiger Anpassung von React-Komponenten erstellen","Sponsorenkarten mit maßgeschneiderten Stilen und Funktionalitäten entwickeln"],"pt":["Injetar conteúdo promocional em feeds de prompt usando widgets de prompt padrão","Criar componentes interativos personalizados com personalização completa de componentes React","Desenvolver cartões de patrocinador com estilização e funcionalidade personalizadas"],"ru":["Внедрение промо-контента в потоки подсказок с помощью стандартных виджетов подсказок","Создание пользовательских интерактивных компонентов с полной настройкой компонентов React","Разработка спонсорских карточек с индивидуальным стилем и функциональностью"],"ar":["إدخال المحتوى الترويجي في تدفقات التلميح باستخدام أدوات التلميح القياسية ","إنشاء مكونات تفاعلية مخصصة مع تخصيص كامل لمكونات React ","تطوير بطاقات الرعاة بأسلوب ووظائف مخصصة"]},"limitations":{"en":["Requires knowledge of React for custom widget development","Limited to prompts.chat platform for widget injection","Dependent on user input for widget creation and customization"],"zh":["需要React知识来进行自定义小部件开发","仅限于prompts.chat平台进行小部件注入","依赖于用户输入来创建和自定义小部件"],"ja":["カスタムウィジェット開発のためにReactの知識が必要","プロンプトフィードへのウィジェット注入はprompts.chatプラットフォームに限定","ウィジェットの作成とカスタマイズにはユーザー入力が必要"],"ko":["사용자 지정 위젯 개발을 위해 React 지식이 필요합니다.","위젯 삽입은 prompts.chat 플랫폼에만 제한됩니다.","위젯 생성 및 사용자 지정에는 사용자 입력이 필요합니다."],"es":["Requiere conocimiento de React para el desarrollo de widgets personalizados","Limitado a la plataforma prompts.chat para la inyección de widgets","Dependiente de la entrada del usuario para la creación y personalización de widgets"],"fr":["Nécessite des connaissances en React pour le développement de widgets personnalisés","Limité à la plateforme prompts.chat pour l''injection de widgets","Dépend de la saisie de l''utilisateur pour la création et la personnalisation de widgets"],"de":["Benötigt Kenntnisse von React für die Entwicklung benutzerdefinierter Widgets","Begrenzt auf die prompts.chat-Plattform für die Einbindung von Widgets","Abhängig von der Benutzereingabe für die Erstellung und Anpassung von Widgets"],"pt":["Exige conhecimento de React para desenvolvimento de widgets personalizados","Limitado à plataforma prompts.chat para injeção de widgets","Dependente da entrada do usuário para criação e personalização de widgets"],"ru":["Требует знания React для разработки пользовательских виджетов","Ограничен платформой prompts.chat для внедрения виджетов","Зависит от ввода пользователя для создания и настройки виджетов"],"ar":["يتطلب معرفة React لتطوير أدوات مخصصة ","محدود منصة prompts.chat لإدخال الأدوات ","يعتمد على مدخلات المستخدم لإنشاء أدوات وتخصيصها"]},"version":3},"contentHash":"efc37f2fc7345b6a79558613f4ead2c44df8a13525cb8d7bc69a332d9241b442","qualityScore":43}');
