INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vicanso/zedis/generate-component-story', 'generate-component-story', 'vicanso', 'zedis', 'community', 'generate-component-story vicanso zedis community gpui redis redis-client Zedis是一个基于Rust和GPUI的快速Redis GUI，用于提高开发效率 Zedisは、RustとGPUIで構築された高速のRedis GUIです。 Zedis는 러스트와 GPUI로 구축된 빠른 Redis GUI입니다. Zedis es una GUI de Redis rápida y nativa construida con Rust y GPUI, ideal para generar componentes de historia Zedis est une interface utilisateur Redis rapide et native créée avec Rust et GPUI, idéale pour générer des composants d''histoire Zedis ist eine schnelle und native Redis-GUI, die mit Rust und GPUI erstellt wurde, ideal zum Erstellen von Komponenten-Geschichten Zedis é uma ferramenta de IA que gera componentes com um cliente Redis GUI rápido e nativo, construído com Rust e GPUI. Aprenda a usá-lo para melhorar a produtividade Зедис - это инструмент ИИ, который генерирует компоненты с быстрым и родным клиентом Redis GUI, построенным на Rust и GPUI. Узнайте, как им пользоваться для повышения производительности زيدس هي أداة ذكاء اصطناعي لإنشاء مكونات مع واجهة مستخدم رسيس سريعة وأصلية مبنية على روست وجي بي يو آي. تعلم كيفية استخدامها لتحسين الإنتاجية Zedis: A blazing-fast, native Redis GUI built with Rust and GPUI. 如何使用Zedis 什么是Redis GUI Zedis替代品 Zedis vs Redis Desktop Manager Zedis安装 Zedis设置指南 Redis客户端工具 GPUI Redis Zedis: A blazing-fast, native Redis GUI built with Rust and GPUI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bigalorm/bigal/enforcing-typescript-standards', 'community', 'bigalorm', 'bigal', 'bigalorm/bigal', 'enforcing-typescript-standards', 9, 2, 43, '2026-02-27T04:49:09Z', '2026-02-27T13:11:57.128Z', '4b3438ff1ce7938cadbdb4772a601dd11fdfdecb1ee44c554bc34a6e213f21cd', '{"id":"bigalorm/bigal/enforcing-typescript-standards","name":"enforcing-typescript-standards","description":{"zh":"一个快速、轻量的ORM，用于PostgreSQL和node.js，采用Typescript编写","ja":"PostgreSQLとnode.js用の高速軽量のORM、TypeScriptで書かれ","ko":"PostgreSQL과 node.js를 위한 빠르고 가벼운 ORM, 타입스크립트로 작성","es":"Enforcing-typescript-standards es un ORM rápido y ligero para PostgreSQL y node.js, escrito en TypeScript, que mejora la productividad","fr":"Enforcing-typescript-standards est un ORM rapide et léger pour PostgreSQL et node.js, écrit en TypeScript, qui améliore la productivité","de":"Enforcing-typescript-standards ist ein schnelles und leichtiges ORM für PostgreSQL und node.js, geschrieben in TypeScript, das die Produktivität steigert","pt":"Um ORM leve e rápido para PostgreSQL e Node.js, escrito em TypeScript, para desenvolver aplicativos de forma eficiente","ru":"Легкий и быстрый ORM для PostgreSQL и Node.js, написанный на TypeScript, для эффективного развития приложений","ar":"ORM خفيف وسريع لبرنامج PostgreSQL و Node.js، مكتوب بلغة TypeScript، لتطوير التطبيقات بفعالية","en":"A fast, lightweight ORM for PostgreSQL and node.js, written in Typescript."},"seo":{"title":{"zh":"AIエージェント：Typescript标准 ORM 解决方案","ja":"AIエージェント：高速軽量のTypeScript ORM","ko":"AI 에이전트: 타입스크립트 표준 ORM 솔루션","es":"Herramientas de TypeScript: Enforcing estándares con ORM","fr":"Outils TypeScript: Enforcing des normes avec ORM","de":"AI-Tools für TypeScript: Enforcing-Standards mit ORM","pt":"Ferramentas de IA: Enforcing TypeScript Standards","ru":"ИИ Агенты: реализация стандартов TypeScript","ar":"أدوات الذكاء الاصطناعي: تطبيق معايير TypeScript","en":"enforcing-typescript-standards"},"description":{"zh":"一个快速、轻量的ORM，用于PostgreSQL和node.js，采用Typescript编写","ja":"PostgreSQLとnode.js用の高速軽量のORM、TypeScriptで書かれ","ko":"PostgreSQL과 node.js를 위한 빠르고 가벼운 ORM, 타입스크립트로 작성","es":"Enforcing-typescript-standards es un ORM rápido y ligero para PostgreSQL y node.js, escrito en TypeScript, que mejora la productividad","fr":"Enforcing-typescript-standards est un ORM rapide et léger pour PostgreSQL et node.js, écrit en TypeScript, qui améliore la productivité","de":"Enforcing-typescript-standards ist ein schnelles und leichtiges ORM für PostgreSQL und node.js, geschrieben in TypeScript, das die Produktivität steigert","pt":"Um ORM leve e rápido para PostgreSQL e Node.js, escrito em TypeScript, para desenvolver aplicativos de forma eficiente","ru":"Легкий и быстрый ORM для PostgreSQL и Node.js, написанный на TypeScript, для эффективного развития приложений","ar":"ORM خفيف وسريع لبرنامج PostgreSQL و Node.js، مكتوب بلغة TypeScript، لتطوير التطبيقات بفعالية","en":"A fast, lightweight ORM for PostgreSQL and node.js, written in Typescript."},"definition":{"en":"A fast, lightweight ORM for PostgreSQL and node.js, written in Typescript."},"features":{"zh":["快速轻量的ORM","支持PostgreSQL和node.js","采用Typescript编写","提高开发效率","轻松集成"],"ja":["高速軽量のORM","PostgreSQLとnode.jsをサポート","TypeScriptで書かれ","開発効率の向上","簡単な統合"],"ko":["빠르고 가벼운 ORM","PostgreSQL과 node.js 지원","타입스크립트로 작성","개발 효율성 향상","쉽게 통합"],"es":["ORM rápido y ligero para PostgreSQL","Escrito en TypeScript para mejorar la productividad","Compatibilidad con node.js","Soporte para Hacktoberfest","Integración con bases de datos relacionales"],"fr":["ORM rapide et léger pour PostgreSQL","Écrit en TypeScript pour améliorer la productivité","Compatibilité avec node.js","Support pour Hacktoberfest","Intégration avec des bases de données relationnelles"],"de":["Schnelles und leichtiges ORM für PostgreSQL","Geschrieben in TypeScript für die Steigerung der Produktivität","Kompatibilität mit node.js","Unterstützung für Hacktoberfest","Integration mit relationalen Datenbanken"],"pt":["ORM leve e rápido para PostgreSQL","Desenvolvido em TypeScript","Compatível com Node.js","Fácil de usar e configurar","Suporte a transações e consultas complexas"],"ru":["Легкий и быстрый ORM для PostgreSQL","Написанный на TypeScript","Компатибельный с Node.js","Легко использовать и настраивать","Поддержка транзакций и сложных запросов"],"ar":["ORM خفيف وسريع لبرنامج PostgreSQL","مكتوب بلغة TypeScript","متوافق مع Node.js","سهل الاستخدام والتهيئة","دعم المعاملات والاستعلامات المعقدة"]},"keywords":{"zh":["AIエージェント","Typescript标准","ORM解决方案","PostgreSQL","node.js","开发效率","如何使用Typescript ORM","Typescript ORM教程"],"ja":["AIエージェント","TypeScript標準","ORMソリューション","PostgreSQL","node.js","開発効率","TypeScript ORMの使い方","TypeScript ORMチュートリアル"],"ko":["AI 에이전트","타입스크립트 표준","ORM 솔루션","PostgreSQL","node.js","개발 효율성","타입스크립트 ORM 사용법","타입스크립트 ORM 튜토리얼"],"es":["cómo usar TypeScript","ORM para PostgreSQL","alternativas a Sequelize","TypeScript vs JavaScript","instalación de ORM","guía de configuración de TypeScript","mejores prácticas de TypeScript","desarrollo de aplicaciones con node.js y PostgreSQL"],"fr":["comment utiliser TypeScript","ORM pour PostgreSQL","alternatives à Sequelize","TypeScript vs JavaScript","installation d''ORM","guide de configuration de TypeScript","meilleures pratiques de TypeScript","développement d''applications avec node.js et PostgreSQL"],"de":["wie man TypeScript verwendet","ORM für PostgreSQL","Alternativen zu Sequelize","TypeScript vs JavaScript","Installation von ORM","Konfigurationsanleitung für TypeScript","Best Practices für TypeScript","Entwicklung von Anwendungen mit node.js und PostgreSQL"],"pt":["como usar TypeScript","o que é ORM","alternativas para Sequelize","TypeScript vs JavaScript","instalar TypeScript","guia de configuração do TypeScript"],"ru":["как использовать TypeScript","что такое ORM","альтернативы для Sequelize","TypeScript vs JavaScript","установить TypeScript","руководство по настройке TypeScript"],"ar":["كيفية استخدام TypeScript","ما هي ORM","بديلات لبرنامج Sequelize","TypeScript مقابل JavaScript","تثبيت TypeScript","دليل إعداد TypeScript"]}},"owner":"bigalorm","repo":"bigal","repoPath":"bigalorm/bigal","stars":9,"forks":2,"updatedAt":"2026-02-27T04:49:09Z","topics":["hacktoberfest","hacktoberfest2022","hacktoberfest2023","nodejs","orm","postgres"],"category":"community","skillMd":{"name":"enforcing-typescript-standards","description":"Enforces the projects core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules. ALWAYS apply when creating, modifying, or reviewing any TypeScript (.ts/.tsx) file.","bodyPreview":"# Enforcing TypeScript Standards\n\nEnforces the project''s core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules.\n\n## Triggers\n\nActivate this skill when the user says or implies any of these:\n\n- \"write\", \"create\", \"implement\", \"add\", \"build\" (new TypeScript code)\n- \"fix\", \"update\", \"change\", \"modify\", \"refactor\" (existing TypeScript code)\n- \"review\", \"check\", \"improve\", \"clean up\" (code quality)\n- Any request involving `.ts` or `.tsx","body":"# Enforcing TypeScript Standards\n\nEnforces the project''s core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules.\n\n## Triggers\n\nActivate this skill when the user says or implies any of these:\n\n- \"write\", \"create\", \"implement\", \"add\", \"build\" (new TypeScript code)\n- \"fix\", \"update\", \"change\", \"modify\", \"refactor\" (existing TypeScript code)\n- \"review\", \"check\", \"improve\", \"clean up\" (code quality)\n- Any request involving `.ts` or `.tsx` files\n\nSpecific triggers:\n\n- Creating a new `.ts` or `.tsx` file\n- Modifying existing TypeScript code\n- Reviewing TypeScript code for compliance\n\n## Core Standards\n\n### Type Safety\n\n- **Explicit return types**: Prefer explicit return types when practical; omit when inference is obvious and adds no clarity\n- **Explicit member accessibility**: Class members require `public`, `private`, or `protected`\n- **Type-only imports**: Use `import type` for types: `import type { Foo } from ''./foo.js''`\n- **Sorted type constituents**: Union/intersection types must be alphabetically sorted\n- **Only throw Error objects**: Never throw strings or other primitives\n- **Avoid `any` and type assertions**: Prefer proper typing over `any` or `as` casts; use them only when truly necessary\n- **Type JSON fields explicitly**: Use `Record<string, unknown>` or specific interfaces for JSON data, never `any`\n- **Use Number() for conversion**: Prefer `Number(value)` over `parseInt(value, 10)` or `parseFloat(value)`\n- **Reuse existing types**: Before defining a new interface, search for existing types that can be reused directly, extended, or derived using `Pick`, `Omit`, `Partial`, or other utility types\n\n#### Alternatives to Type Assertions\n\nBefore using `as`, try these approaches in order:\n\n1. Proper typing at the source\n2. Type guards (`typeof`, `instanceof`)\n3. Type narrowing through control flow\n4. Custom type predicate functions\n5. Discriminated unions\n\n```ts\n// Bad\nconst user = data as User;\n\n// Good\nfunction isUser(data: unknown): data is User {\n  return typeof data === ''object'' && data !== null && ''id'' in data;\n}\nif (isUser(data)) {\n  // data is now typed as User\n}\n```\n\n### Import Organization\n\n- **Import order**: built-in → external → internal → parent → sibling → index (alphabetized within groups)\n- **No duplicate imports**: Consolidate imports from the same module\n- **Newline after imports**: Empty line required after import block\n\n### Class Member Ordering\n\n1. Signatures (call/construct)\n2. Fields: private → public → protected\n3. Constructors: public → protected → private\n4. Methods: public → protected → private\n\n### Code Style\n\n- **Simplicity over cleverness**: Straightforward, readable code is better than clever one-liners\n- **Early returns**: Use guard clauses to reduce nesting; return early for edge cases\n- **Nullish coalescing**: Prefer `??` over `||` for defaults (avoids false positives on `0` or `''''`)\n- **Optional chaining**: Use `?.` for safe property access\n- **Match existing patterns**: Follow conventions already established in the codebase\n- **Meaningful identifiers**: Names must be descriptive (exceptions: `_`, `i`, `j`, `k`, `e`, `x`, `y`)\n- **Function declarations**: Use `function foo()` not `const foo = function()`\n- **Prefer const**: Use `const` unless reassignment is needed\n- **No var**: Always use `const` or `let`\n- **Object shorthand**: Use `{ foo }` not `{ foo: foo }`\n- **Template literals**: Use `` `Hello ${name}` `` not `''Hello '' + name`\n- **Strict equality**: Use `===` except for null comparisons\n- **One class per file**: Maximum one class definition per file\n- **Avoid `reduce`**: Prefer `for...of` loops or other array methods for clarity\n- **Functions over classes**: Prefer exported functions over classes with static methods (unless state is needed)\n- **No nested functions**: Define helper functions at module level, not inside other functions\n- **Immutability**: Create new objects/arrays instead of mutating existing ones\n\n### Naming Conventions\n\n- **Enum members**: Use `PascalCase` (e.g., `MyValue`)\n- **No trailing underscores**: Identifiers cannot end with `_`\n\n### Comments\n\n- **No redundant comments**: Never comment what the code already expresses clearly\n- **No duplicate comments**: Don''t repeat information from function names, types, or nearby comments\n- **Meaningful only**: Only add comments to explain _why_, not _what_ — the code shows what it does\n\n### Boolean Expressions\n\n- **Prefer truthiness checks**: Use implicit truthy/falsy checks over explicit comparisons\n- **Exception**: Use explicit checks when distinguishing `0`/`''''` (valid values) from `null`/`undefined` is semantically important\n\n### Testing\n\n- **Minimize mocking**: Avoid mocking everything; use real implementations and data generators when available\n- **Test real behavior**: Testing mocks provides little value — test actual code paths\n- **Don''t be lazy**: Write thorough tests that cover edge cases, not just happy paths\n\n### Error Handling\n\n- **Specific error types**: Prefer specific error types over generic `Error` when meaningful\n- **Avoid silent failures**: Don''t swallow errors with empty catch blocks\n- **Handle rejections**: Always handle promise rejections\n- **Let errors propagate**: Don''t catch errors just to re-throw or log — let them bubble up to error handlers\n\n## Negative Knowledge\n\nAvoid these antipatterns:\n\n- `console.log()` statements in production code\n- `eval()` or `Function()` constructor\n- Nested ternary operators\n- `await` inside loops when `Promise.all` would be simpler (sequential awaits are fine when order matters or parallelism adds complexity)\n- Empty interfaces\n- Variable shadowing\n- Functions defined inside loops\n- `@ts-ignore` without explanation (use `@ts-expect-error` with 10+ char description)\n- Comments that restate the code: `// increment counter` above `counter++`\n- Comments that duplicate type information: `// returns a string` when return type is `: string`\n- Commented-out code (delete it; use version control)\n- Verbose boolean comparisons: `arr.length > 0`, `str !== ''''`, `obj !== null && obj !== undefined`\n- Disabling linter rules via comments (fix the code instead)\n- Overuse of `any` type or `as` type assertions\n- Over-mocking in tests instead of using real implementations or data generators\n- Empty catch blocks that silently swallow errors\n- Using `||` for defaults when `??` is more appropriate\n- Deep nesting when early returns would simplify\n- Catching errors just to re-throw or log them\n- Nested function definitions inside other functions\n- Mutating objects/arrays instead of creating new ones\n- TOCTOU: Checking file/resource existence before operating (try and handle errors instead)\n- Classes with only static methods (use plain functions instead)\n- Duplicating existing interfaces instead of reusing or deriving with `Pick`/`Omit`/`Partial`\n\n## Verification Workflow\n\n1. **Analyze**: Compare the code change against these TypeScript standards\n2. **Generate/Refactor**: Write or modify code to comply with all rules above\n3. **Simplify**: Review for opportunities to simplify — prefer clear, straightforward code over clever solutions\n4. **Review naming**: Verify variable and function names still make sense in context after changes\n5. **Build**: Verify types compile without errors (e.g., `npm run build` or `npx tsc --noEmit`)\n6. **Lint**: Run `npm run lint` to confirm compliance before completing the task\n\n## Examples\n\n### Comments Examples\n\n```ts\n// Standard\n// Retry with exponential backoff to handle transient network failures\nasync function fetchWithRetry(url: string, attempts = 3): Promise<Response> {\n  for (let i = 0; i < attempts; i++) {\n    try {\n      return await fetch(url);\n    } catch {\n      await sleep(2 ** i * 100);\n    }\n  }\n  throw new Error(`Failed after ${attempts} attempts`);\n}\n\n// Non-Standard\n/**\n * Fetches data from a URL with retry logic\n * @param url - The URL to fetch from\n * @param attempts - Number of attempts (default 3)\n * @returns A Promise that resolves to a Response\n */\nasync function fetchWithRetry(url: string, attempts = 3): Promise<Response> {\n  // Loop through attempts\n  for (let i = 0; i < attempts; i++) {\n    try {\n      // Try to fetch the URL\n      return await fetch(url);\n    } catch {\n      // Wait before retrying\n      await sleep(2 ** i * 100);\n    }\n  }\n  // Throw error if all attempts fail\n  throw new Error(`Failed after ${attempts} attempts`);\n}\n```\n\n### Boolean Expressions Examples\n\n```ts\n// Standard\nif (myArray.length) {\n}\nif (myString) {\n}\nif (myObject) {\n}\nif (!value) {\n}\n\n// Non-Standard\nif (myArray.length !== 0) {\n}\nif (myArray.length > 0) {\n}\nif (myString !== '''') {\n}\nif (myObject !== null && myObject !== undefined) {\n}\nif (value === null || value === undefined) {\n}\n```\n\n### Early Return Examples\n\n```ts\n// Standard\nfunction processUser(user: User | null): Result {\n  if (!user) {\n    return { error: ''No user provided'' };\n  }\n  if (!user.isActive) {\n    return { error: ''User is inactive'' };\n  }\n  return { data: transform(user) };\n}\n\n// Non-Standard\nfunction processUser(user: User | null): Result {\n  if (user) {\n    if (user.isActive) {\n      return { data: transform(user) };\n    } else {\n      return { error: ''User is inactive'' };\n    }\n  } else {\n    return { error: ''No user provided'' };\n  }\n}\n```\n\n### Functions Over Classes Examples\n\n```ts\n// Standard\nexport function calculateTotal(items: Item[]): number {\n  return items.reduce((sum, item) => sum + item.price, 0);\n}\n\nexport function formatCurrency(amount: number): string {\n  return `$${amount.toFixed(2)}`;\n}\n\n// Non-Standard\nexport class Calculator {\n  static calculateTotal(items: Item[]): number {\n    return items.reduce((sum, item) => sum + item.price, 0);\n  }\n\n  static formatCurrency(amount: number): string {\n    return `$${amount.toFixed(2)}`;\n  }\n}\n```\n\n### No Nested Functions Examples\n\n```ts\n// Standard\nfunction transformItem(item: Item): TransformedItem {\n  return { id: item.id, name: item.name.toUpperCase() };\n}\n\nasync function processItems(items: Item[]): Promise<TransformedItem[]> {\n  return items.map(transformItem);\n}\n\n// Non-Standard\nasync function processItems(items: Item[]): Promise<TransformedItem[]> {\n  function transformItem(item: Item): TransformedItem {\n    return { id: item.id, name: item.name.toUpperCase() };\n  }\n  return items.map(transformItem);\n}\n```\n\n### Immutability Examples\n\n```ts\n// Standard\nfunction addItem(items: Item[], newItem: Item): Item[] {\n  return [...items, newItem];\n}\n\nfunction removeItem(items: Item[], id: string): Item[] {\n  return items.filter((item) => item.id !== id);\n}\n\nfunction updateItem(items: Item[], id: string, updates: Partial<Item>): Item[] {\n  return items.map((item) => (item.id === id ? { ...item, ...updates } : item));\n}\n\n// Non-Standard\nfunction addItem(items: Item[], newItem: Item): Item[] {\n  items.push(newItem);\n  return items;\n}\n\nfunction removeItem(items: Item[], id: string): Item[] {\n  const index = items.findIndex((item) => item.id === id);\n  items.splice(index, 1);\n  return items;\n}\n```\n\n### Error Propagation Examples\n\n```ts\n// Standard\nasync function getUser(id: string): Promise<User> {\n  return userService.findById(id);\n}\n\n// Non-Standard\nasync function getUser(id: string): Promise<User> {\n  try {\n    return await userService.findById(id);\n  } catch (error) {\n    console.error(error);\n    throw error;\n  }\n}\n```\n\n### TOCTOU Examples\n\n```ts\n// Standard\nasync function readConfig(path: string): Promise<Config> {\n  try {\n    const content = await readFile(path, ''utf-8'');\n    return JSON.parse(content);\n  } catch (error) {\n    if (isNotFoundError(error)) {\n      return defaultConfig;\n    }\n    throw error;\n  }\n}\n\n// Non-Standard\nasync function readConfig(path: string): Promise<Config> {\n  if (await fileExists(path)) {\n    const content = await readFile(path, ''utf-8'');\n    return JSON.parse(content);\n  }\n  return defaultConfig;\n}\n```\n\n### Type Reuse Examples\n\n```ts\n// Given an existing type\ninterface User {\n  id: string;\n  email: string;\n  name: string;\n  passwordHash: string;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\n// Standard - derive from existing type\ntype PublicUser = Omit<User, ''passwordHash''>;\ntype UserSummary = Pick<User, ''id'' | ''name''>;\ntype UserUpdate = Partial<Pick<User, ''email'' | ''name''>>;\n\n// Non-Standard - duplicating fields that already exist\ninterface PublicUser {\n  id: string;\n  email: string;\n  name: string;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\ninterface UserSummary {\n  id: string;\n  name: string;\n}\n\ninterface UserUpdate {\n  email?: string;\n  name?: string;\n}\n```\n"},"lastSynced":"2026-02-27T13:11:57.128Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Maintenance Agents requiring strict adherence to TypeScript standards and best practices.","zh":"适用于需要严格遵守TypeScript标准和最佳实践的代码维护代理。","ja":"TypeScriptの標準とベストプラクティスに厳格に従う必要があるコードメンテナンスエージェントに適しています。","ko":"TypeScript 표준과 최고의 관행을 엄격하게 준수해야 하는 코드 유지 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento de Código que requieren una estricta adhesión a los estándares y mejores prácticas de TypeScript.","fr":"Idéal pour les Agents de Maintenance de Code nécessitant une stricte adhésion aux normes et aux meilleures pratiques de TypeScript.","de":"Ideal für Code-Wartungsagenten, die eine strikte Einhaltung der TypeScript-Standards und -Best Practices erfordern.","pt":"Ideal para Agentes de Manutenção de Código que exigem adesão estrita aos padrões e melhores práticas do TypeScript.","ru":"Идеально подходит для агентов по обслуживанию кода, требующих строгого соблюдения стандартов и лучших практик TypeScript.","ar":"مثالي للوكلاء الذين يحتاجون إلى اتباع صارم لمعايير وأفضل الممارسات الخاصة بلغة TypeScript."},"recommendation":{"en":"Empowers agents to enforce explicit typing, organize imports, order class members, and apply code safety rules, ensuring high-quality TypeScript codebases with PostgreSQL and node.js integrations.","zh":"赋予代理人执行显式类型、组织导入、排序类成员并应用代码安全规则的能力，确保具有PostgreSQL和node.js集成的高质量TypeScript代码库。","ja":"明示的な型付け、インポートの整理、クラスメンバーの並び替え、およびコードの安全性ルールの適用をエージェントに可能にし、PostgreSQLおよびnode.jsとの統合を備えた高品質のTypeScriptコードベースを保証します。","ko":"명시적 유형 지정, 가져오기 구성, 클래스 구성원 순서 지정 및 코드 안전 규칙 적용과 같은 기능을 에이전트에게 부여하여 PostgreSQL 및 node.js와의 통합을 갖춘 높은 품질의 TypeScript 코드베이스를 보장합니다.","es":"Habilita a los agentes a aplicar tipificación explícita, organizar importaciones, ordenar miembros de clase y aplicar reglas de seguridad de código, garantizando bases de código de TypeScript de alta calidad con integraciones de PostgreSQL y node.js.","fr":"Permet aux agents d''appliquer une typification explicite, d''organiser les importations, d''ordonner les membres de classe et d''appliquer des règles de sécurité de code, garantissant ainsi des bases de code TypeScript de haute qualité avec des intégrations PostgreSQL et node.js.","de":"Ermächtigt Agenten, explizite Typisierung durchzusetzen, Importe zu organisieren, Klassenmitglieder zu ordnen und Code-Sicherheitsregeln anzuwenden, um hochwertige TypeScript-Codebasen mit PostgreSQL- und node.js-Integrationen sicherzustellen.","pt":"Habilita os agentes a impor digitação explícita, organizar imports, ordenar membros de classe e aplicar regras de segurança de código, garantindo bases de código TypeScript de alta qualidade com integrações PostgreSQL e node.js.","ru":"Наделяет агентов возможностью обеспечивать явное типизирование, организовывать импорт, упорядочивать членов класса и применять правила безопасности кода, гарантируя высококачественные базы кода TypeScript с интеграциями PostgreSQL и node.js.","ar":"يمنح الوكلاء القدرة على فرض الكتابة 明确، تنظيم الاستيراد، وترتيب أعضاء الفئة، وتطبيق قواعد سلامة الكود، مما يحقق قواعد بيانات TypeScript عالية الجودة مع التكاملات PostgreSQL و node.js."},"useCases":{"en":["Implementing explicit typing for new TypeScript code","Refactoring existing code to meet project TypeScript standards","Reviewing and improving code quality for .ts and .tsx files"],"zh":["为新的TypeScript代码实现显式类型","将现有代码重构为满足项目TypeScript标准","审查和提高.ts和.tsx文件的代码质量"],"ja":["新しいTypeScriptコードのための明示的な型付けの実装","プロジェクトのTypeScript標準を満たすために既存のコードのリファクタリング",".tsおよび.tsxファイルのコード品質のレビューおよび改善"],"ko":["新的 TypeScript 코드를 위한 명시적 유형 지정 구현","프로젝트의 TypeScript 표준을 충족하기 위해 기존 코드를 리팩토링",".ts 및 .tsx 파일의 코드 품질 검토 및 개선"],"es":["Implementar tipificación explícita para nuevo código TypeScript","Reestructurar código existente para cumplir con los estándares de TypeScript del proyecto","Revisar y mejorar la calidad del código para archivos .ts y .tsx"],"fr":["Mettre en œuvre une typification explicite pour le nouveau code TypeScript","Réorganiser le code existant pour répondre aux normes de TypeScript du projet","Réviser et améliorer la qualité du code pour les fichiers .ts et .tsx"],"de":["Explizite Typisierung für neuen TypeScript-Code implementieren","Bestehenden Code neu strukturieren, um die TypeScript-Standards des Projekts zu erfüllen","Code-Qualität für .ts- und .tsx-Dateien überprüfen und verbessern"],"pt":["Implementar digitação explícita para novo código TypeScript","Reestruturar código existente para atender aos padrões do projeto TypeScript","Revisar e melhorar a qualidade do código para arquivos .ts e .tsx"],"ru":["Реализация явного типизирования для нового кода TypeScript","Перестройка существующего кода для соответствия стандартам проекта TypeScript","Проверка и улучшение качества кода для файлов .ts и .tsx"],"ar":["تنفيذ الكتابة明确 للكود TypeScript الجديد","إعادة هيكلة الكود الحالي لتناسب معايير المشروع TypeScript","مراجعة وتحسين جودة الكود لملفات .ts و .tsx"]},"limitations":{"en":["Requires TypeScript configuration and setup","Limited to TypeScript projects, specifically those using PostgreSQL and node.js"],"zh":["需要TypeScript配置和设置","仅限于使用PostgreSQL和node.js的TypeScript项目"],"ja":["TypeScriptの設定とセットアップが必要","PostgreSQLおよびnode.jsを使用するTypeScriptプロジェクトに限定される"],"ko":["TypeScript 구성 및 설정이 필요","PostgreSQL 및 node.js를 사용하는 TypeScript 프로젝트에만 제한"],"es":["Requiere configuración y configuración de TypeScript","Limitado a proyectos TypeScript, específicamente aquellos que utilizan PostgreSQL y node.js"],"fr":["Nécessite une configuration et une installation de TypeScript","Limité aux projets TypeScript, en particulier ceux qui utilisent PostgreSQL et node.js"],"de":["Benötigt TypeScript-Konfiguration und -Einrichtung","Begrenzt auf TypeScript-Projekte, insbesondere solche, die PostgreSQL und node.js verwenden"],"pt":["Exige configuração e instalação do TypeScript","Limitado a projetos TypeScript, especificamente aqueles que utilizam PostgreSQL e node.js"],"ru":["Требует настройки и установки TypeScript","Ограничен проектами TypeScript, в частности теми, которые используют PostgreSQL и node.js"],"ar":["يتطلب تكوين وإعداد لغة TypeScript","محدود بمشاريع TypeScript، تحديدا تلك التي تستخدم PostgreSQL و node.js"]},"version":3},"contentHash":"4b3438ff1ce7938cadbdb4772a601dd11fdfdecb1ee44c554bc34a6e213f21cd","qualityScore":43}');
