INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('termos-dev/agent-workbench/awb', 'awb', 'termos-dev', 'agent-workbench', 'community', 'awb termos-dev agent-workbench community AWB是 Claude Code 的交互式开发环境，提供了快速开发和测试的功能 AWBは Claude Code のインタラクティブ開発環境であり、迅速な開発とテスト機能を提供する AWB는 Claude Code의 인터랙티브 개발 환경으로 빠른 개발과 테스트 기능을 제공한다 awb es un entorno de desarrollo interactivo para Claude Code que ofrece componentes interactivos y de visualización. awb est un environnement de développement interactif pour Claude Code qui propose des composants interactifs et de visualisation. awb ist eine interaktive Entwicklungsumgebung für Claude Code, die interaktive und visuelle Komponenten bietet. O AWB é uma ferramenta de desenvolvimento interativo para Claude Code, permitindo a criação de experiências personalizadas com componentes como confirm, checklist e ask. AWB - это интерактивная среда разработки для Claude Code, позволяющая создавать персонализированные trải nghiệm с компонентами seperti confirm, checklist и ask. AWB هي أداة تطوير تفاعلية ل Claude Code، تمكن من إنشاء تجارب مخصصة مع مكونات مثل confirm و checklist و ask. Interactive Development Environment for Claude Code AWB 交互式开发环境 Claude Code 快速开发 代码测试 组件化开发 Interactive Development Environment for Claude Code ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dmmulroy/better-result/better-result-adopt', 'community', 'dmmulroy', 'better-result', 'dmmulroy/better-result', 'better-result-adopt', 0, 0, 43, '2026-03-04T13:07:01.667Z', '2026-03-04T13:22:04.678Z', '5f1b3cfb868955a2ff39a188c3d0191c1c70e75e13b5af48d412f35658e8dc03', '{"id":"dmmulroy/better-result/better-result-adopt","name":"better-result-adopt","description":{"zh":"better-result 提供了一种轻量级的 TypeScript 结果类型，用于简化错误处理和提高代码可靠性","ja":"better-resultはTypeScript向けの軽量結果タイプを提供し、エラーハンドリングを簡素化しコードの信頼性を向上させます","ko":"better-result는 TypeScript용 가벼운 결과 유형을 제공하여 오류 처리를 단순화하고 코드의 안정성을 향상시킵니다","es":"better-result es una biblioteca ligera para TypeScript que permite una composición basada en generadores para el manejo de errores","fr":"better-result est une bibliothèque légère pour TypeScript qui permet une composition basée sur des générateurs pour la gestion des erreurs","de":"better-result ist eine leichte Bibliothek für TypeScript, die eine generatorbasierte Zusammensetzung für die Fehlerbehandlung ermöglicht","pt":"better-result é uma biblioteca leve para TypeScript que fornece uma forma de lidar com erros de maneira tipada e eficiente.","ru":"better-result — это лёгкая библиотека для TypeScript, которая предоставляет способ обработки ошибок типизированным и эффективным образом.","ar":"better-result هو مكتبة خفيفة الوزن ل TypeScript توفر طريقة للتعامل مع الأخطاء بطريقة مميزة و فعالة.","en":"Lightweight Result type for TypeScript with generator-based composition."},"seo":{"title":{"zh":"better-result 采用：轻量级 TypeScript 结果类型","ja":"better-result 導入：TypeScript 向け軽量結果タイプ","ko":"better-result採用：軽量级 TypeScript 결과 유형","es":"Mejora tus resultados con better-result","fr":"Améliorez vos résultats avec better-result","de":"Bessere Ergebnisse mit better-result","pt":"Melhorando Resultados com better-result","ru":"Улучшение результатов с better-result","ar":"تحسين النتائج مع better-result","en":"better-result-adopt"},"description":{"zh":"better-result 提供了一种轻量级的 TypeScript 结果类型，用于简化错误处理和提高代码可靠性","ja":"better-resultはTypeScript向けの軽量結果タイプを提供し、エラーハンドリングを簡素化しコードの信頼性を向上させます","ko":"better-result는 TypeScript용 가벼운 결과 유형을 제공하여 오류 처리를 단순화하고 코드의 안정성을 향상시킵니다","es":"better-result es una biblioteca ligera para TypeScript que permite una composición basada en generadores para el manejo de errores","fr":"better-result est une bibliothèque légère pour TypeScript qui permet une composition basée sur des générateurs pour la gestion des erreurs","de":"better-result ist eine leichte Bibliothek für TypeScript, die eine generatorbasierte Zusammensetzung für die Fehlerbehandlung ermöglicht","pt":"better-result é uma biblioteca leve para TypeScript que fornece uma forma de lidar com erros de maneira tipada e eficiente.","ru":"better-result — это лёгкая библиотека для TypeScript, которая предоставляет способ обработки ошибок типизированным и эффективным образом.","ar":"better-result هو مكتبة خفيفة الوزن ل TypeScript توفر طريقة للتعامل مع الأخطاء بطريقة مميزة و فعالة.","en":"Lightweight Result type for TypeScript with generator-based composition."},"definition":{"en":"Lightweight Result type for TypeScript with generator-based composition."},"features":{"zh":["轻量级结果类型","generator-based 组合","类型化错误处理","Promise rejection 处理","铁路导向编程模式"],"ja":["軽量結果タイプ","generator-based 組み合わせ","型付きエラーハンドリング","Promise rejection 処理","鉄道指向プログラミングパターン"],"ko":["가벼운 결과 유형","generator-based 조합","유형화된 오류 처리","Promise 거부 처리","철도 지향 프로그래밍 패턴"],"es":["Manejo de errores tipados","Composición basada en generadores","Migración de try/catch y Promise rejections","Introducción de patrones de programación orientados a railway","Reemplazo de excepciones lanzadas con errores tipados"],"fr":["Gestion des erreurs typées","Composition basée sur des générateurs","Migration de try/catch et de rejets de Promise","Introduction de modèles de programmation orientés railway","Remplacement d''exceptions lancées avec des erreurs typées"],"de":["Typisierte Fehlerbehandlung","Generatorbasierte Zusammensetzung","Migration von try/catch und Promise-Ablehnungen","Einführung von Eisenbahn-orientierten Programmiermustern","Ersetzen von geworfenen Ausnahmen durch typisierte Fehler"],"pt":["Tipagem de erros","Composição baseada em geradores","Substituição de blocos try/catch","Suporte a Promise","Padrões de programação orientados a trilhos"],"ru":["Типизация ошибок","Композиция на основе генераторов","Замена блоков try/catch","Поддержка Promise","Шаблоны программирования, ориентированные на железнодорожные пути"],"ar":["تصنيف الأخطاء","التركيب المستندة إلى المولدات","استبدال كتل try/catch","دعم Promise","أنماط البرمجة الموجهة إلى سكة حديد"]},"keywords":{"zh":["TypeScript","结果类型","错误处理","轻量级","generator-based","铁路导向编程"],"ja":["TypeScript","結果タイプ","エラーハンドリング","軽量","generator-based","鉄道指向プログラミング"],"ko":["TypeScript","결과 유형","오류 처리","가벼운","generator-based","철도 지향 프로그래밍"],"es":["better-result","TypeScript","manejo de errores","composición basada en generadores","migración de try/catch","reemplazo de excepciones","programación orientada a railway","errores tipados"],"fr":["better-result","TypeScript","gestion des erreurs","composition basée sur des générateurs","migration de try/catch","remplacement d''exceptions","programmation orientée railway","erreurs typées"],"de":["better-result","TypeScript","Fehlerbehandlung","generatorbasierte Zusammensetzung","Migration von try/catch","Ersetzen von Ausnahmen","Eisenbahn-orientierte Programmierung","typisierte Fehler"],"pt":["better-result","TypeScript","erros tipados","manipulação de erros","Result types","geradores","Promise","programação orientada a trilhos"],"ru":["better-result","TypeScript","типизированные ошибки","обработка ошибок","Result types","генераторы","Promise","программирование, ориентированное на железнодорожные пути"],"ar":["better-result","TypeScript","أخطاء مميزة","التعامل مع الأخطاء","Result types","مولدات","Promise","برمجة موجهة إلى سكة حديد"]}},"owner":"dmmulroy","repo":"better-result","repoPath":"dmmulroy/better-result","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.667Z","topics":[],"category":"community","skillMd":{"name":"better-result-adopt","description":"Migrate codebase from try/catch or Promise-based error handling to better-result. Use when adopting Result types, converting thrown exceptions to typed errors, or refactoring existing error handling to railway-oriented programming.","bodyPreview":"# better-result Adoption\n\nMigrate existing error handling (try/catch, Promise rejections, thrown exceptions) to typed Result-based error handling with better-result.\n\n## When to Use\n\n- Adopting better-result in existing codebase\n- Converting try/catch blocks to Result types\n- Replacing thrown exceptions with typed errors\n- Migrating Promise-based code to Result.tryPromise\n- Introducing railway-oriented programming patterns\n\n## Migration Strategy\n\n### 1. Start at Boundaries\n\nBegin migration at I/","body":"# better-result Adoption\n\nMigrate existing error handling (try/catch, Promise rejections, thrown exceptions) to typed Result-based error handling with better-result.\n\n## When to Use\n\n- Adopting better-result in existing codebase\n- Converting try/catch blocks to Result types\n- Replacing thrown exceptions with typed errors\n- Migrating Promise-based code to Result.tryPromise\n- Introducing railway-oriented programming patterns\n\n## Migration Strategy\n\n### 1. Start at Boundaries\n\nBegin migration at I/O boundaries (API calls, DB queries, file ops) and work inward. Don''t attempt full-codebase migration at once.\n\n### 2. Identify Error Categories\n\nBefore migrating, categorize errors in target code:\n\n| Category       | Example                | Migration Target                                |\n| -------------- | ---------------------- | ----------------------------------------------- |\n| Domain errors  | NotFound, Validation   | TaggedError + Result.err                        |\n| Infrastructure | Network, DB connection | Result.tryPromise + TaggedError                 |\n| Bugs/defects   | null deref, type error | Let throw (becomes Panic if in Result callback) |\n\n### 3. Migration Order\n\n1. Define TaggedError classes for domain errors\n2. Wrap throwing functions with Result.try/tryPromise\n3. Convert imperative error checks to Result chains\n4. Refactor callbacks to generator composition\n\n## Pattern Transformations\n\n### Try/Catch to Result.try\n\n```typescript\n// BEFORE\nfunction parseConfig(json: string): Config {\n  try {\n    return JSON.parse(json);\n  } catch (e) {\n    throw new ParseError(e);\n  }\n}\n\n// AFTER\nfunction parseConfig(json: string): Result<Config, ParseError> {\n  return Result.try({\n    try: () => JSON.parse(json) as Config,\n    catch: (e) => new ParseError({ cause: e, message: `Parse failed: ${e}` }),\n  });\n}\n```\n\n### Async/Await to Result.tryPromise\n\n```typescript\n// BEFORE\nasync function fetchUser(id: string): Promise<User> {\n  const res = await fetch(`/api/users/${id}`);\n  if (!res.ok) throw new ApiError(res.status);\n  return res.json();\n}\n\n// AFTER\nasync function fetchUser(id: string): Promise<Result<User, ApiError | UnhandledException>> {\n  return Result.tryPromise({\n    try: async () => {\n      const res = await fetch(`/api/users/${id}`);\n      if (!res.ok) throw new ApiError({ status: res.status, message: `API ${res.status}` });\n      return res.json() as Promise<User>;\n    },\n    catch: (e) => (e instanceof ApiError ? e : new UnhandledException({ cause: e })),\n  });\n}\n```\n\n### Null Checks to Result\n\n```typescript\n// BEFORE\nfunction findUser(id: string): User | null {\n  return users.find((u) => u.id === id) ?? null;\n}\n// Caller must check: if (user === null) ...\n\n// AFTER\nfunction findUser(id: string): Result<User, NotFoundError> {\n  const user = users.find((u) => u.id === id);\n  return user\n    ? Result.ok(user)\n    : Result.err(new NotFoundError({ id, message: `User ${id} not found` }));\n}\n// Caller: yield* findUser(id) in Result.gen, or .match()\n```\n\n### Callback Hell to Generator\n\n```typescript\n// BEFORE\nasync function processOrder(orderId: string) {\n  try {\n    const order = await fetchOrder(orderId);\n    if (!order) throw new NotFoundError(orderId);\n    const validated = validateOrder(order);\n    if (!validated.ok) throw new ValidationError(validated.errors);\n    const result = await submitOrder(validated.data);\n    return result;\n  } catch (e) {\n    if (e instanceof NotFoundError) return { error: \"not_found\" };\n    if (e instanceof ValidationError) return { error: \"invalid\" };\n    throw e;\n  }\n}\n\n// AFTER\nasync function processOrder(orderId: string): Promise<Result<OrderResult, OrderError>> {\n  return Result.gen(async function* () {\n    const order = yield* Result.await(fetchOrder(orderId));\n    const validated = yield* validateOrder(order);\n    const result = yield* Result.await(submitOrder(validated));\n    return Result.ok(result);\n  });\n}\n// Error type is union of all yielded errors\n```\n\n## Defining TaggedErrors\n\nSee [references/tagged-errors.md](references/tagged-errors.md) for TaggedError patterns.\n\n## Workflow\n\n1. **Check for source reference**: Look for `opensrc/` directory - if present, read the better-result source code for implementation details and patterns\n2. **Audit**: Find try/catch, Promise.catch, thrown errors in target module\n3. **Define errors**: Create TaggedError classes for domain errors\n4. **Wrap boundaries**: Use Result.try/tryPromise at I/O points\n5. **Chain operations**: Convert if/else error checks to .andThen or Result.gen\n6. **Update signatures**: Change return types to Result<T, E>\n7. **Update callers**: Propagate Result handling up call stack\n8. **Test**: Verify error paths with .match or type narrowing\n\n## Common Pitfalls\n\n- **Over-wrapping**: Don''t wrap every function. Start at boundaries, propagate inward.\n- **Losing error info**: Always include cause/context in TaggedError constructors.\n- **Mixing paradigms**: Once a module returns Result, callers should too (or explicitly .unwrap).\n- **Ignoring Panic**: Callbacks that throw become Panic. Fix the bug, don''t catch Panic.\n\n## References\n\n- [TaggedError Patterns](references/tagged-errors.md) - Defining and matching typed errors\n- `opensrc/` directory (if present) - Full better-result source code for deeper context\n"},"lastSynced":"2026-03-04T13:22:04.678Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript Agents needing robust error handling with Result types and generator-based composition.","zh":"适合于需要使用 Result 类型和基于生成器的组合进行强大的错误处理的 TypeScript 代理。","ja":"TypeScript エージェントが堅牢なエラーハンドリングと Result 型および生成ベースの構成を必要とする場合に最適です。","ko":"강력한 에러 처리를 위해 Result 유형과 생성기 기반 구성이 필요한 TypeScript 에이전트에 적합합니다.","es":"Perfecto para Agentes de TypeScript que necesitan un control de errores robusto con tipos de Resultado y composición basada en generadores.","fr":"Parfait pour les agents TypeScript qui ont besoin d''une gestion d''erreurs robuste avec des types de résultat et une composition basée sur des générateurs.","de":"Perfekt für TypeScript-Agents, die eine robuste Fehlerbehandlung mit Result-Typen und generatorbasierte Zusammensetzung benötigen.","pt":"Perfeito para Agentes TypeScript que necessitam de tratamento de erros robusto com tipos Result e composição baseada em geradores.","ru":"Идеально для агентов TypeScript, требующих надежной обработки ошибок с помощью типов Result и генераторной композиции.","ar":"مثالي للوكلاء النمطية التي تحتاج إلى معالجة الخطأ القوية مع أنواع النتيجة والتركيب المبني على المولدات."},"recommendation":{"en":"Empowers agents to migrate existing error handling to typed Result-based error handling with better-result, utilizing railway-oriented programming patterns and replacing thrown exceptions with typed errors, while also supporting Promise-based code migration to Result.tryPromise.","zh":"赋予代理以更好的结果利用铁路导向的编程模式，将抛出的异常替换为类型化错误的能力，同时也支持将基于 Promise 的代码迁移到 Result.tryPromise。","ja":"エージェントは既存のエラーハンドリングを Result 型のエラーハンドリングに移行し、鉄道指向のプログラミングパターンを利用して、スローされた例外を型付けされたエラーに置き換えることができ、Promise ベースのコードを Result.tryPromise に移行することもサポートします。","ko":"에이전트가 기존의 에러 처리를 Result 기반의 에러 처리로 마이그레이션할 수 있으며, 철도 지향 프로그래밍 패턴을 사용하여 던져진 예외를 유형화된 오류로 대체할 수 있고, Promise 기반 코드를 Result.tryPromise로 마이그레이션하는 것도 지원합니다.","es":"Habilita a los agentes a migrar el control de errores existente a un control de errores basado en Resultado con mejor resultado, utilizando patrones de programación orientada a ferrocarril y reemplazando excepciones lanzadas con errores tipados, y también admite la migración de código basado en Promesas a Result.tryPromise.","fr":"Permet aux agents de migrer la gestion des erreurs existante vers une gestion des erreurs basée sur les types de résultat avec un meilleur résultat, en utilisant des modèles de programmation orientés chemin de fer et en remplaçant les exceptions lancées par des erreurs typées, tout en prenant en charge la migration de code basé sur les promesses vers Result.tryPromise.","de":"Ermächtigt Agents, die vorhandene Fehlerbehandlung auf eine typsichere Fehlerbehandlung mit Result-Typen und besseren Ergebnissen zu migrieren, unter Verwendung von schienengebundenen Programmiermustern und durch Ersetzen von ausgelösten Ausnahmen mit typsicheren Fehlern, und unterstützt auch die Migration von Promise-basiertem Code zu Result.tryPromise.","pt":"Habilita os agentes a migrar o tratamento de erros existente para o tratamento de erros baseado em Result com melhor resultado, utilizando padrões de programação orientada a trilhos e substituindo exceções lançadas por erros tipados, além de suportar a migração de código baseado em Promessa para Result.tryPromise.","ru":"Наделяет агентов возможностью мигрировать существующую обработку ошибок на типизированную обработку ошибок на основе Result с лучшим результатом, используя шаблоны программирования, ориентированные на железную дорогу, и заменяя выбрасываемые исключения типизированными ошибками, а также поддерживая миграцию кода на основе Promises в Result.tryPromise.","ar":"تمكّن الوكلاء من هجرة معالجة الخطأ الحالية إلى معالجة الخطأ المُقاسة بناءً على النتيجة مع نتيجة أفضل، واستخدام أنماط البرمجة الموجهة إلى السكك الحديدية، واستبدال الاستثناءات المُلقاة بالأخطاء المُقاسة، بالإضافة إلى دعم هجرة رمز Promise إلى Result.tryPromise."},"useCases":{"en":["Converting try/catch blocks to Result types for improved error management","Migrating Promise-based code to Result.tryPromise for better error handling","Introducing railway-oriented programming patterns for more robust code composition"],"zh":["将 try/catch 块转换为 Result 类型以改善错误管理","将基于 Promise 的代码迁移到 Result.tryPromise 以获得更好的错误处理","引入铁路导向的编程模式以实现更强大的代码组合"],"ja":["try/catch ブロックを Result 型に変換してエラーマネージメントを改善する","Promise ベースのコードを Result.tryPromise に移行してエラーハンドリングを改善する","鉄道指向のプログラミングパターンを導入してコード構成をより強固にする"],"ko":["try/catch 블록을 Result 유형으로 변환하여 오류 관리를 개선하는 것","Promise 기반 코드를 Result.tryPromise로 마이그레이션하여 더好的 오류 처리를 하는 것","철도 지향 프로그래밍 패턴을 도입하여 더 강력한 코드 구성에 기여하는 것"],"es":["Convertir bloques try/catch en tipos de Resultado para una mejor gestión de errores","Migrar código basado en Promesas a Result.tryPromise para una mejor gestión de errores","Introducir patrones de programación orientada a ferrocarril para una composición de código más robusta"],"fr":["Convertir les blocs try/catch en types de résultat pour une meilleure gestion des erreurs","Migrer le code basé sur les promesses vers Result.tryPromise pour une meilleure gestion des erreurs","Introduire des modèles de programmation orientés chemin de fer pour une composition de code plus robuste"],"de":["Umwandeln von try/catch-Blöcken in Result-Typen für eine verbesserte Fehlerverwaltung","Migration von Promise-basiertem Code zu Result.tryPromise für eine bessere Fehlerverwaltung","Einführung von schienengebundenen Programmiermustern für eine robustere Codezusammensetzung"],"pt":["Conversão de blocos try/catch para tipos Result para melhor gerenciamento de erros","Migração de código baseado em Promessa para Result.tryPromise para melhor tratamento de erros","Introdução de padrões de programação orientada a trilhos para composição de código mais robusta"],"ru":["Преобразование блоков try/catch в типы Result для улучшения управления ошибками","Миграция кода на основе Promises в Result.tryPromise для лучшей обработки ошибок","Введение шаблонов программирования, ориентированных на железную дорогу, для более прочной композиции кода"],"ar":["تحويل كتل Try/Catch إلى أنواع النتيجة من أجل إدارة أفضل للأخطاء","هجرة رمز Promise إلى Result.tryPromise من أجل معالجة أفضل للأخطاء","إدخال أنماط البرمجة الموجهة إلى السكك الحديدية من أجل تركيب رمز أكثر متانة"]},"limitations":{"en":["Requires TypeScript environment","Initial migration efforts required at code boundaries"],"zh":["需要 TypeScript 环境","代码边界需要初始迁移努力"],"ja":["TypeScript 環境が必要","コード境界では初期の移行努力が必要"],"ko":["TypeScript 환경이 필요함","코드 경계에서 초기 마이그레이션 노력이 필요함"],"es":["Requiere un entorno de TypeScript","Se requieren esfuerzos iniciales de migración en los límites del código"],"fr":["Nécessite un environnement TypeScript","Des efforts initiaux de migration sont nécessaires aux limites du code"],"de":["Benötigt eine TypeScript-Umgebung","Anfangs sind Migrationsbemühungen an den Codegrenzen erforderlich"],"pt":["Requer ambiente TypeScript","Esforços iniciais de migração necessários nas fronteiras do código"],"ru":["Требуется среда TypeScript","Первоначальные усилия по миграции необходимы на границах кода"],"ar":["يتطلب بيئة النمطية","جهود هجرة أولية مطلوبة على حدود الرمز"]},"version":3},"contentHash":"5f1b3cfb868955a2ff39a188c3d0191c1c70e75e13b5af48d412f35658e8dc03","qualityScore":43}');
