INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Fergana-Labs/claude_agent_desktop/word', 'word', 'Fergana-Labs', 'claude_agent_desktop', 'community', 'word Fergana-Labs claude_agent_desktop community Word是一个GUI封装，基于Claude Agent SDK，用于构建智能交互应用 Wordは、Claude Agent SDKを使用したGUIラッパーで、スマートな対話アプリケーションを構築 Word는 Claude Agent SDK 기반의 GUI 래퍼로, 스마트한 대화 애플리케이션을 구축 Nuestra GUI wrapper se basa en Claude Agent SDK para ofrecer una integración sencilla y eficiente para desarrolladores Notre GUI wrapper est basé sur Claude Agent SDK pour offrir une intégration simple et efficace pour les développeurs Unsere GUI-Wrapper basiert auf Claude Agent SDK, um eine einfache und effiziente Integration für Entwickler zu bieten O word é uma ferramenta de interação de GUI construída em cima do Claude Agent SDK, permitindo a criação de interfaces de usuário gráficas para agentes de IA. ИИ Агенты: word - это GUI-оболочка, построенная на основе Claude Agent SDK, позволяющая создавать графические интерфейсы для ИИ Агентов. أداة كلام هي أداة واجهة المستخدم الرسومية مبنية على sdk عميل كلود، مما يتيح إنشاء واجهات مستخدم رسومية لعميل كلود. GUI wrapper built on top of Claude Agent SDK AI智能代理 Claude Agent SDK GUI封装 智能交互应用 如何使用Word Word教程 Word与Claude Agent SDK比较 Word安装指南 Word设置教程 GUI wrapper built on top of Claude Agent SDK');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tkgally/je-dict-1/kanji-index', 'community', 'tkgally', 'je-dict-1', 'tkgally/je-dict-1', 'kanji-index', 0, 0, 43, '2026-03-04T13:07:01.686Z', '2026-03-04T13:25:43.047Z', 'acb8c46495f018bf2964a1f072ced2e851e7997860107c57f47cd84a3676c14d', '{"id":"tkgally/je-dict-1/kanji-index","name":"kanji-index","description":{"zh":"kanji-index是一个日语英语学习字典，提供海量词汇和例句，帮助开发者提高日语水平","ja":"kanji-indexは日本語英語学習辞書で、多数の語彙と例文を提供し、開発者の日本語力を向上させる","ko":"kanji-index는 일본어 영어 학습 사전으로,大量의 어휘와 예문을 제공하여 개발자의 일본어 실력을 향상 시킵니다","es":"kanji-index es un diccionario de aprendizaje japonés-inglés en progreso para desarrolladores que buscan mejorar sus habilidades en japonés","fr":"kanji-index est un dictionnaire d''apprentissage japonais-anglais en cours de réalisation pour les développeurs qui souhaitent améliorer leurs compétences en japonais","de":"kanji-index ist ein japanisch-englisches Lernwörterbuch in Entwicklung für Entwickler, die ihre Fähigkeiten im Japanischen verbessern möchten","pt":"O kanji-index é um dicionário em desenvolvimento para aprendizes de japonês-inglês, criado para ajudar no desenvolvimento de habilidades linguísticas","ru":"kanji-index - это словарь в разработке для изучающих японский-английский язык, предназначенный для помощи в развитии языковых навыков","ar":"kanji-index هو قاموس قيد التطوير للطلاب اليابانيين-الإنكليز، تم إنشاؤه لمساعدة في تطوير المهارات اللغوية","en":"In-progress Japanese-English learner''s dictionary"},"seo":{"title":{"zh":"AI工具：kanji-index日语英语学习字典","ja":"AIエージェント：kanji-index日本語英語学習辞書","ko":"AI 에이전트: kanji-index 일본어 영어 학습 사전","es":"Herramientas de AI: kanji-index para desarrolladores","fr":"Outils d''IA: kanji-index pour les développeurs","de":"KI-Tools: kanji-index für Entwickler","pt":"Ferramentas de IA: kanji-index para Desenvolvedores","ru":"ИИ Агенты: kanji-index для Разработчиков","ar":"أدوا