INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Clay-Ferguson/mkbrowser/app-pages', 'app-pages', 'Clay-Ferguson', 'mkbrowser', 'community', 'app-pages Clay-Ferguson mkbrowser community app-pages 是一个 Electron 桌面应用，提供文件浏览和 Markdown 浏览/编辑功能 app-pages は Electron デスクトップアプリで、ファイルブラウザと Markdown ブラウザ/エディタ機能を提供 app-pages는 Electron 데스크탑 애플리케이션으로, 파일 탐색기 및 Markdown 브라우저/편집기 기능을 제공 app-pages es una aplicación de escritorio Electron que integra un explorador de archivos y un editor de Markdown para desarrolladores app-pages est une application de bureau Electron qui intègre un explorateur de fichiers et un éditeur de Markdown pour les développeurs app-pages ist eine Electron-Desktop-Anwendung, die einen Datei-Explorer und einen Markdown-Editor für Entwickler integriert O App-Pages é uma aplicação de desktop Electron que combina um navegador de arquivos e um editor de Markdown, facilitando o desenvolvimento de aplicações App-Pages - это электронное приложение для настольных компьютеров, которое объединяет проводник файлов и редактор Markdown, упрощая разработку приложений تطبيق App-Pages هو تطبيق سطح المكتب إلكتروني يدمج متصفح ملفات ومحرر Markdown، مما يسهل تطوير التطبيقات File Explorer and Markdown Browser/Editor (Electron Desktop App) 如何使用app-pages app-pages 教程 Electron 桌面应用开发 Markdown 编辑器 文件浏览器 app-pages 安装 app-pages 设置指南 File Explorer and Markdown Browser/Editor (Electron Desktop App) ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gpad1234/skills-imaginary-guide-agent/system-health', 'community', 'gpad1234', 'skills-imaginary-guide-agent', 'gpad1234/skills-imaginary-guide-agent', 'system-health', 0, 0, 43, '2026-03-04T13:07:01.769Z', '2026-03-04T14:20:10.347Z', '2c2d88ffaee233d2bace4eb64ea7dc2f094c7a5aa4d9c87b5864616f0b5eb6e7', '{"id":"gpad1234/skills-imaginary-guide-agent/system-health","name":"system-health","description":{"zh":"系统健康监测技能可以帮助开发者优化系统性能，添加系统健康监测技能到MCP","ja":"システムヘルスチェック機能を使用してシステムのパフォーマンスを最適化し、MCPに追加する","ko":"시스템 헬스 체크 기능을 사용하여 시스템 성능을 최적화하고 MCP에 추가합니다","es":"System-health es una habilidad de AI Agent que permite agregar funcionalidades a MCP para mejorar la salud del sistema.","fr":"System-health est une compétence d''Agent IA qui permet d''ajouter des fonctionnalités à MCP pour améliorer la santé du système.","de":"System-health ist eine Fähigkeit von AI-Agent, die es ermöglicht, Funktionen zu MCP hinzuzufügen, um die Systemgesundheit zu verbessern.","pt":"O sistema de saúde é uma habilidade que permite adicionar funcionalidades ao MCP. Aprenda a usar as ferramentas de AI para melhorar a eficiência do seu sistema.","ru":"Система здоровья - это умение, которое позволяет добавлять функциональность в MCP. Узнайте, как использовать ИИ Агенты для повышения эффективности вашей системы.","ar":"نظام الصحة هو مهارة تسمح بإضافة وظيفية إلى MCP. تعلم كيف تستخدم أدوات الذكاء الاصطناعي لتحسين كفاءة نظامك.","en":"adding skills to mcp"},"seo":{"title":{"zh":"AI智能体系统健康监测","ja":"AIエージェントのシステムヘルスチェック","ko":"AI 에이전트 시스템 헬스 체크","es":"Herramientas de AI Agent: system-health para MCP","fr":"Outils d''Agent IA: system-health pour MCP","de":"AI-Agent-Tools: system-health für MCP","pt":"Ferramentas de AI: Sistema de Saúde para MCP","ru":"ИИ Агенты: Система Здоровья для MCP","ar":"أدوات الذكاء الاصطناعي: نظام الصحة لبرنامج MCP","en":"system-