INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hdkiller/coach/reka-ui', 'reka-ui', 'hdkiller', 'coach', 'community', 'reka-ui hdkiller coach community reka-ui是您的开源AI教练和统一健身仪表盘，帮助您提升开发效率 reka-uiはオープンソースのAIコーチと統一されたフィットネスダッシュボードで、開発の効率を上げることができます reka-ui는 오픈소스의 AI 코치와 통합된 피트니스 대시보드로 개발 효율을 높여줍니다 reka-ui es un coach de IA de código abierto y un tablero de fitness unificado para ayudarte a alcanzar tus objetivos reka-ui est un coach d''IA open source et un tableau de fitness unifié pour vous aider à atteindre vos objectifs reka-ui ist ein KI-Coach mit Open-Source-Code und ein einheitliches Fitness-Dashboard, um Ihnen bei der Erreichung Ihrer Ziele zu helfen O reka-ui é uma plataforma de treinamento de IA aberta e unificada para fitness, projetada para ajudar você a melhorar sua rotina de exercícios. reka-ui - открытый ИИ Агент и единая панель фитнеса, предназначенная для улучшения вашей тренировочной программы. reka-ui هي منصة التدريب الاصطناعي المفتوحة والموحدة لللياقة البدنية، مصممة لمساعدتك على تحسين نظامك الرياضي. Your open source AI coach and unified fitness dashboard. 如何使用reka-ui 什么是AI教练 reka-ui替代品 reka-ui vs 其他AI工具 reka-ui安装 reka-ui设置指南 AI开发工具 开发效率提升 Your open source AI coach and unified fitness dashboard.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sf-bcca/PromptArchitect-Studio/supabase-architect', 'community', 'sf-bcca', 'PromptArchitect-Studio', 'sf-bcca/PromptArchitect-Studio', 'supabase-architect', 0, 0, 43, '2026-03-04T13:07:01.896Z', '2026-03-04T14:56:19.601Z', '27669c7de100848f4a3e92a67d412488b0b111b96ca65877c992c9d72816d6a2', '{"id":"sf-bcca/PromptArchitect-Studio/supabase-architect","name":"supabase-architect","description":{"zh":"Supabase Architect AI智能代理是一种用于构建精心设计的AI提示的web应用，帮助开发者提高开发效率","ja":"Supabase Architect AIエージェントは、考慮されたAIプロンプトを作成するためのwebアプリケーションであり、開発者の開発効率を向上させるのに役立ちます","ko":"Supabase Architect AI 에이전트는 잘 짜여진 AI 프롬프트を作成하는 웹 애플리케이션으로, 개발자들의 개발 효율성을 높여줍니다","es":"Supabase Architect es una herramienta de desarrollo que permite crear promts de IA bien diseñados. Aprende a utilizarla para mejorar tus proyectos","fr":"Supabase Architect est un outil de développement qui permet de créer des invites d''IA bien conçus. Apprenez à l''utiliser pour améliorer vos projets","de":"Supabase Architect ist ein Entwicklungstool, mit dem Sie gut durchdachte AI-Prompts erstellen können. Lernen Sie, wie Sie es verwenden können, um Ihre Projekte zu verbessern","pt":"O supabase-architect é uma ferramenta de criação de prompts de AI que ajuda desenvolvedores a criar soluções personalizadas","ru":"supabase-architect - это инструмент для создания запросов ИИ, который помогает разработчикам создавать индивидуальные решения","ar":"supabase-architect هو أداة لإنشاء محفزات الذكاء الاصطناعي تساعد المطورين على إنشاء حلول مخصصة","en":"Thoughtfully create well crafted AI prompts with this web app."},"seo":{"title":{"zh":"Supabase Architect AI智能代理 - 构建精心设计的AI提示","ja":"Supabase Architect AIエージェント - 考慮されたAIプロンプトを作成","ko":"Supabase Architect AI 에이전트 - 잘 짜여진 AI 프롬프트を作成","es":"Herramientas de AI: Supabase Architect","fr":"Outils d''IA: Supabase Architect","de":"KI-Tools