INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bretstarr2024/The-Long-Walk/end-session', 'end-session', 'bretstarr2024', 'The-Long-Walk', 'community', 'end-session bretstarr2024 The-Long-Walk community End-Session是一款基于Stephen King的The Long Walk的生存模拟游戏，使用Vite + TypeScript + GPT-5.2开发 End-Sessionは、スティーブン・キングのThe Long Walkに基づくサバイバルシミュレーションゲームです。Vite + TypeScript + GPT-5.2を使用して開発されています End-Session는 스티븐 킹의 The Long Walk를 기반으로 하는 생存 시뮬레이션 게임입니다. Vite + TypeScript + GPT-5.2로 개발되었습니다 El juego de supervivencia The Long Walk utiliza agentes de IA como GPT-5.2 con Vite y TypeScript para una experiencia de juego única Le jeu de survie The Long Walk utilise des agents IA comme GPT-5.2 avec Vite et TypeScript pour une expérience de jeu unique Das Überlebensspiel The Long Walk nutzt KI-Agenten wie GPT-5.2 mit Vite und TypeScript für ein einzigartiges Spielerlebnis O agente End-Session é um jogo de simulação de sobrevivência baseado em The Long Walk, de Stephen King, desenvolvido com Vite, TypeScript e GPT-5.2. Oferece uma experiência única de jogo. Агент End-Session - симуляционная игра о выживании по мотивам The Long Walk Стивена Кинга, разработанная на Vite, TypeScript и GPT-5.2. Предоставляет уникальный игровой опыт. وكلاء النهاية الجلسة هم لعبة محاكاة البقاء تعتمد على رواية ستيفن كينج، تم تطويرها باستخدام Vite و TypeScript و GPT-5.2. توفر تجربة فريدة من نوعها. Survival simulation game based on Stephen King''s The Long Walk. Vite + TypeScript + GPT-5.2 agents. AI工具 生存模拟游戏 The Long Walk Vite TypeScript GPT-5.2 如何使用End-Session End-Session教程 AI工具集成 跨平台游戏开发 Survival simulation game based on Stephen King''s The Long Walk. Vite + TypeScript + GPT-5.2 agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('takuto-tanaka-4digit/excel-unidiff-cli/euni-commands-guide', 'community', 'takuto-tanaka-4digit', 'excel-unidiff-cli', 'takuto-tanaka-4digit/excel-unidiff-cli', 'euni-commands-guide', 0, 0, 42, '2026-02-27T01:22:47Z', '2026-02-28T14:52:49.796Z', '8a76a59a292ed44f2a7ef6c3781bce30645aaea3b92a7d290d873e30efb6f634', '{"id":"takuto-tanaka-4digit/excel-unidiff-cli/euni-commands-guide","name":"euni-commands-guide","description":{"zh":"euni-commands-guide是一个跨平台的CLI工具，用于检测和修正Git仓库和子模块中的Unicode规范化问题","ja":"euni-commands-guideは、GitリポジトリとサブモジュールのUnicode正規化問題を検出・修正するためのクロスプラットフォームCLIツールです","ko":"euni-commands-guide는 Git 저장소와 서브모듈의 유니코드 규칙화 문제를检测하고 수정하는 크로스 플랫폼 CLI 도구입니다","es":"La guía de comandos euni es una herramienta de línea de comandos que detecta y corrige diferencias de normalización Unicode en repositorios y submódulos","fr":"Le guide de commandes euni est un outil en ligne de commande qui détecte et corrige les différences de normalisation Unicode dans les référentiels et sous-modules","de":"Der Euni-Kommando-Guide ist ein Kommandozeilen-Tool, das Unterschiede in der Unicode-Normalisierung in Repositories und Submodulen erkennt und korrigiert","pt":"A ferramenta euni-commands-guide é uma CLI cross-platform para detectar e corrigir problemas de normalização Unicode em repositórios Git","ru":"Инструмент euni-commands-guide является кроссплатформенной CLI для обнаружения и исправления проблем нормализации Юникода в репозиториях Git","ar":"أداة euni-commands-guide هي واجهة سطر أوامر متعددة المنصات للكشف عن مشاكل تعديل يونيكود وتجنب التغييرات الوهمية في ملفات إكسل","en":"Cross-platform CLI to detect and fix Unicode normalization (NFC/NFD) Git diffs in repositories and submodules, preventing phantom Excel file   changes across macOS, Linux, and Windows CI runners."},"seo":{"title":{"zh":"AIエージェント：euni-commands-guide