INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EthanAlgoX/MarketBot/gog', 'gog', 'EthanAlgoX', 'MarketBot', 'community', 'gog EthanAlgoX MarketBot community Gog AI代理技能是市场智能和交易分析的专用AI代理，用于提供市场分析和交易决策支持 Gog AIエージェントスキルは、市場インテリジェンスとトレーディング分析のための専用AIエージェントです Gog AI 에이전트 스킬은 시장 지능 및 거래 분석을 위한 전용 AI 에이전트입니다 gog es una herramienta de línea de comandos que permite automatizar tareas en Gmail, Calendar, Drive y otros servicios de Google. Requiere configuración de OAuth. gog est un outil de ligne de commande qui permet d''automatiser des tâches dans Gmail, Calendar, Drive et d''autres services Google. Nécessite une configuration OAuth. gog ist ein Kommandozeilen-Tool, das die Automatisierung von Aufgaben in Gmail, Calendar, Drive und anderen Google-Diensten ermöglicht. Erfordert OAuth-Konfiguration. O gog é uma ferramenta de linha de comando para integração com serviços do Google, como Gmail e Google Drive. Ele permite a automação de tarefas e consultas. gog - это утилита командной строки для интеграции с сервисами Google, такими как Gmail и Google Drive. Он позволяет автоматизировать задачи и запросы. gog هو أداة سطر أوامر للتحكم في تطبيقات جوجل المختلفة مثل جيميل و جوجل درايف. يمكنه توفير الوقت والجهد من خلال Automação والاستعلامات. MarketBot is a finance-customized version of openclaw, built as a dedicated AI agent for market intelligence, trading analysis, and decision support. Gog AI代理技能 市场智能 交易分析 决策支持 Gmail集成 OAuth认证 MarketBot is a finance-customized version of openclaw, built as a dedicated AI agent for market intelligence, trading analysis, and decision support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pyinx/ceo-skills-plugin/ceo', 'community', 'pyinx', 'ceo-skills-plugin', 'pyinx/ceo-skills-plugin', 'ceo', 0, 0, 42, '2026-03-04T13:07:01.665Z', '2026-03-04T13:21:15.453Z', '6e434f81ffef4324e7ea5b5181fe18471b6bcba6a751aefb84b4b026cce5e338', '{"id":"pyinx/ceo-skills-plugin/ceo","name":"ceo","description":{"zh":"CEO Agent是一种全栈开发团队的直接协调工具，集成多个专业agents和Superpowers框架skills","ja":"CEO Agentは、フルスタック開発チームの直接オーケストレーションツールで、複数の専門エージェントとSuperpowersフレームワークスキルを統合しています","ko":"CEO Agent는 풀스택 개발팀의 직접 오케스트레이션 도구로, 여러 전문 에이전트와 Superpowers 프레임워크 스킬을 통합합니다","es":"El CEO Agent es un equipo de desarrollo full stack que integra 6 agentes y 11 habilidades de Superpowers para ofrecer soluciones de software personalizadas","fr":"L''agent CEO est une équipe de développement full stack qui intègre 6 agents et 11 compétences Superpowers pour offrir des solutions logicielles sur mesure","de":"Der CEO Agent ist ein Full-Stack-Entwicklungsteam, das 6 Agenten und 11 Superpowers-Fähigkeiten integriert, um maßgeschneiderte Softwarelösungen anzubieten","pt":"O CEO Agent é uma equipe de desenvolvimento de software completo que oferece uma abordagem integrada para atender às necessidades dos usuários.","ru":"CEO Агент - это полноценная команда разработки программного обеспечения, которая предлагает комплексный подход для удовлетворения потребностей пользователей.","ar":"عميل الرئيس التنفيذي هو فريق تطوير برنامج كامل يقدم نهجًا متكاملًا لتحقيق احتياجات المستخدمين.","en":"从模糊需求到产品交付的全栈开发团队，集成6个专业agents和11个Superpowers框架skills。"},"seo":{"title":{"zh":"CEO Agent - 全栈开发团队的直接协调","ja":"CEO Agent - フルスタック開発チームの直接オーケストレーション","ko":"CEO Agent - 풀스택 개발チーム의 직접 오케스트레이션","es":"CEO Agent: Desarrollo de Software Full Stack","fr":"Agent CEO : Développement Logiciel Full Stack","de":"CEO Agent: Full-Stack-Software-Entwicklung","pt":"CEO Agent: Desenvolvimento de 