INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('galz10/pickle-rick-extension/implementation-planner', 'implementation-planner', 'galz10', 'pickle-rick-extension', 'community', 'implementation-planner galz10 pickle-rick-extension community Implementation Planner是一个AI智能工具，通过Gemini CLI实现超智能的软件开发循环 Implementation Plannerは、Gemini CLIを使用して超智能なソフトウェア開発サイクルを実現するAIエージェントです 구현 계획자는 Gemini CLI를 사용하여 초スマ트한 소프트웨어 개발 사이클을 구현하는 AI 에이전트입니다 Implementation-planner es una extensión que aplica un ciclo de desarrollo de software riguroso y iterativo a través de bucles de agentes de IA Implementation-planner est une extension qui applique un cycle de développement de logiciels rigoureux et itératif à travers des boucles d''agents d''IA Implementation-planner ist eine Erweiterung, die einen strengen und iterativen Softwareentwicklungszyklus durch KI-Agenten-Schleifen anwendet O planejador de implementação transforma o Gemini CLI em uma experiência de desenvolvimento de software hyper-inteligente Планировщик реализации превращает Gemini CLI в гипер-интеллектуальный опыт разработки программного обеспечения مخطط التنفيذ يتحول Gemini CLI إلى تجربة تطوير برمجيات ذكية This extension transforms the Gemini CLI into "Pickle Rick," a hyper-intelligent, arrogant, yet extremely competent engineering persona. It enforces a rigid, iterative software development lifecycle through continuous AI agent loops. Emphasizing "God Mode" coding practices and a disdain for AI智能工具 Implementation Planner Gemini CLI 软件开发自动化 如何使用Implementation Planner Implementation Planner教程 AI工具比较 Implementation Planner安装 Implementation Planner设置指南 This extension transforms the Gemini CLI into "Pickle Rick," a hyper-intelligent, arrogant, yet extremely competent engineering persona. It enforces a rigid, iterative software development lifecycle through continuous AI agent loops. Emphasizing "God Mode" coding practices and a disdain for');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lemline/lemline/core-dev', 'community', 'lemline', 'lemline', 'lemline/lemline', 'core-dev', 0, 0, 42, '2026-03-04T13:07:01.680Z', '2026-03-04T13:24:31.406Z', 'e891aeb18da30381354870b7a33aae591d079eb0292ed29610bedff23a636ab0', '{"id":"lemline/lemline/core-dev","name":"core-dev","description":{"zh":"核心开发AI工具提供服务器无服务工作流DSL运行时，高效、事件驱动、最小化数据库依赖","ja":"コア開発AIエージェントは、サーバーレスワークフローディエスエルランタイムを提供し、高効率でイベント駆動、データベース依存を最小限に抑えます","ko":"코어 개발 AI 에이전트는 서버리스 워크플로우 DSL 런타임을 제공하며, 고성능 이벤트 기반 및 최소한의 데이터베이스 종속성을 특징으로 합니다","es":"core-dev es un runtime de flujo de trabajo serverless para infraestructuras existentes, altamente eficiente y basado en eventos con una dependencia mínima de bases de datos","fr":"core-dev est un runtime de workflow serverless pour les infrastructures existantes, très efficace et basé sur les événements avec une dépendance minimale aux bases de données","de":"core-dev ist eine Serverless-Workflow-Laufzeit für bestehende Infrastrukturen, die sehr effizient und ereignisgesteuert ist und nur minimale Abhängigkeit von Datenbanken aufweist","pt":"O Core-Dev é um runtime de Workflow DSL serverless para infraestrutura existente, projetado para ser highly eficiente e minimamente dependente de bancos de dados","ru":"Core-Dev - это серверный.runtime для Workflow DSL, предназначенный для существующей инфраструктуры, высокоэффективный и минимally зависимый от баз данных","ar":"Core-Dev هو وقت تشغيل Workflow DSL بدون خادم لبيئة موجودة، مصمم ليكون فعالا ومدفوعا بالأحداث مع اعتماد أدنى على قواعد البيانات","en":"Serverless Workflow DSL runtime for existing infrastructure. Highly efficient, event-driven, with minimal database reliance"},"seo":{"title":{"zh":"核心开发AI工具 - 服务器无服务工作流DSL运行时","ja":"コア開発AIエージェント - サーバーレスワークフローディエスエルランタイム","ko":"코어 개발 AI 에이전트 - 서버리스 워크플로우 DSL 런타임","es":"Herramientas de AI: core-dev, runtime de