INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mburdo/knowledge_and_vibes/ground', 'ground', 'Mburdo', 'knowledge_and_vibes', 'community', 'ground Mburdo knowledge_and_vibes community ground栈是为AI智能代理开发者提供的工具、指南、模板和工作流，帮助您从好到伟大 groundスタックは、AIエージェント開発者向けのツール、ガイド、テンプレート、ワークフローを提供し、グッドトゥグレートに支援します ground 스택은 AI 에이전트 개발자를 위한 툴, 가이드, 템플릿, 워크플로우를 제공하여 굿 투 그레이트로 도와드립니다 Ground es una pila de desarrollo de agentes de IA opinionada con herramientas, guías, plantillas y flujos de trabajo para mejorar tus habilidades Ground est une pile de développement d''agents IA avisée avec des outils, des guides, des modèles et des workflows pour améliorer vos compétences Ground ist ein KI-Agents-Entwicklungstack mit Tools, Anleitungen, Vorlagen und Workflows, um Ihre Fähigkeiten zu verbessern Desenvolva soluções de agente de IA de alta qualidade com nossa pilha de desenvolvimento opinada, incluindo ferramentas, guias e fluxos de trabalho para ajudá-lo a criar projetos de sucesso Создавайте высококачественные решения ИИ Агентов с нашей опинированной стека разработки, включающей инструменты, руководства и рабочие процессы для помощи в создании успешных проектов إنشاء حلول وكلاء الذكاء الاصطناعي عالية الجودة باستخدام حزمة تطويرنا المتميزة، بما في ذلك الأدوات والدلائل والعمليات لتساعدك على إنشاء مشاريع ناجحة Opinionated AI agent dev stack with tools, guides, templates, and workflows to take you from good to great. AI智能代理 ground栈 AI开发工具 如何使用ground栈 AI智能代理开发指南 ground栈安装 ground栈设置指南 AI智能代理开发最佳实践 Opinionated AI agent dev stack with tools, guides, templates, and workflows to take you from good to great.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShunsukeHayashi/Miyabi/ccg', 'community', 'ShunsukeHayashi', 'Miyabi', 'ShunsukeHayashi/Miyabi', 'ccg', 0, 0, 42, '2026-03-04T13:07:01.681Z', '2026-03-04T13:24:33.670Z', '0903675e6dc91dab917da75ce76876366651933df8b7bb0857dce8972638a860', '{"id":"ShunsukeHayashi/Miyabi/ccg","name":"ccg","description":{"zh":"CCG是一个开源、经济治理、初学者友好的自主开发框架，基于问题驱动开发","ja":"CCGはオープンソース、経済的ガバナンス、初心者向けの自律型開発フレームワークです","ko":"CCG는 오픈소스, 경제적 거버넌스, 초보자용 자율형 개발 프레임워크입니다","es":"CCG es un marco de desarrollo autónomo que permite a los desarrolladores crear Agentes de IA de manera fácil y eficiente","fr":"CCG est un cadre de développement autonome qui permet aux développeurs de créer des Agents IA de manière facile et efficace","de":"CCG ist ein Rahmenwerk für autonome Entwicklung, das es Entwicklern ermöglicht, KI-Agents einfach und effizient zu erstellen","pt":"O ccg é um framework de desenvolvimento autônomo de código aberto, governado economicamente e fácil de usar, mesmo para iniciantes","ru":"ccg - это первый открытый автономный разработка, управляемый экономикой, и дружественный для начинающих","ar":"ccg هو إطار عمل تطوير ذاتي مفتوح المصدر وحكوم économica وسهل الاستخدام، حتى للمبتدئين","en":"🤖 First open-source, economically-governed, beginner-friendly autonomous development framework built on Issue-Driven Development | 超初心者でも使える自律型開発フレームワーク"},"seo":{"title":{"zh":"AI智能开发框架 - CCG","ja":"AIエージェント開発フレームワーク - CCG","ko":"AI 에이전트 개발 프레임워크 - CCG","es":"Agente de IA CCG: Marco de Desarrollo Autónomo","fr":"Agent IA CCG : Cadre de Développement Autonome","de":"KI-Agent CCG: Rahmenwerk für Autonome Entwicklung","pt":"Ferramentas de IA: ccg - Desenvolvimento Autônomo","ru":"ИИ Агенты: ccg - Автономная Разработка","ar":"أدوات الذكاء الاصطناعي: ccg - إطار عمل تطوير ذاتي","en":"ccg"},"description":{"zh":"CCG是一个开源、经济治理、初学者友好的自主开发框架，基于问题驱动开发","ja":"