INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yu-iskw/lightdash-tools/openspec-explore', 'openspec-explore', 'yu-iskw', 'lightdash-tools', 'community', 'openspec-explore yu-iskw lightdash-tools community openspec-explore是Lightdash工具箱的一部分，提供HTTP客户端、CLI、MCP等强大工具 openspec-exploreはLightdashツールの一つで、HTTPクライアント、CLI、MCPなどの機能を提供します openspec-explore는 라이트대시 도구의 일부로 HTTP 클라이언트, CLI, MCP 등의 강력한 기능을 제공합니다 Lightdash ofrece una variedad de herramientas para desarrolladores, incluyendo un cliente HTTP, CLI, MCP y más, con openspec-explore Lightdash propose une variété d''outils pour les développeurs, notamment un client HTTP, CLI, MCP et plus, avec openspec-explore Lightdash bietet eine Vielzahl von Tools für Entwickler, einschließlich eines HTTP-Clients, CLI, MCP und mehr, mit openspec-explore O openspec-explore é uma ferramenta que oferece recursos avançados de desenvolvimento com Lightdash, incluindo HTTP client, CLI e MCP openspec-explore - это инструмент, который предлагает расширенные возможности разработки с помощью Lightdash, включая HTTP-клиент, CLI и MCP openspec-explore هو أداة تقدم ميزات متقدمة للتطوير باستخدام Lightdash، بما في ذلك العميل HTTP و CLI و MCP Lightdash tools (HTTP client, CLI, MCP and more) 如何使用openspec-explore 什么是Lightdash工具 openspec-explore替代品 Lightdash工具箱安装 openspec-explore设置指南 AI工具openspec-explore Lightdash tools (HTTP client, CLI, MCP and more)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mariotoffia/gobridge/deployment-aws-canary-setup', 'community', 'mariotoffia', 'gobridge', 'mariotoffia/gobridge', 'deployment-aws-canary-setup', 0, 0, 42, '2026-03-04T13:07:01.689Z', '2026-03-04T13:30:57.790Z', 'bf13ba527ac817430840b0c5588dc5da775c8b352f11c3eedea70def1c1fdc7a', '{"id":"mariotoffia/gobridge/deployment-aws-canary-setup","name":"deployment-aws-canary-setup","description":{"zh":"此AI智能代理实现了无状态世界和有状态世界之间的桥接，例如Lambda和MQTT或Azure Service Bus","ja":"このAIエージェントは、ステートレスな世界とステートフルな世界の間のブリッジを提供します。例えば、LambdaとMQTTまたはAzure Service Bus","ko":"이 AI 에이전트는 무상태 세계와 상태FUL 세계 간의 브릿지를 제공합니다. 예를 들어, Lambda와 MQTT 또는 Azure Service Bus","es":"La configuración de canario en AWS es un puente entre el mundo sin estado y el estado, como Lambda y MQTT o Azure Service Bus, permitiendo una integración fluida","fr":"La configuration de canari en AWS est un pont entre le monde sans état et l''état, comme Lambda et MQTT ou Azure Service Bus, permettant une intégration fluide","de":"Die Canary-Release-Konfiguration in AWS ist eine Brücke zwischen der staatenlosen Welt und der staatenreichen Welt, wie Lambda und MQTT oder Azure Service Bus, und ermöglicht eine nahtlose Integration","pt":"O deployment-aws-canary-setup é uma ponte entre o mundo stateless e stateful, permitindo a integração de serviços como Lambda e MQTT","ru":"Deployment-aws-canary-setup является мостом между бесстатным и статным мирами, позволяя интегрировать сервисы, такие как Lambda и MQTT","ar":"deployment-aws-canary-setup هو جسر بين العالم الخالي من الحالة وال世界 الحالم، مما يسمح بدمج خدمات مثل Lambda و MQTT","en":"This is a bridge between the stateless world and the stateful such as Lambda <-> MQTT or Azure Service Bus"},"seo":{"title":{"zh":"AI智能代理 - 部署AWS金丝雀发布","ja":"AIエージェント - AWSカナリアリリースの設定","ko":"AI 에이전트 - AWS 카나리 배포 설정","es":"Herramientas de AI: Configuración de canario en AWS","fr":"Outils d''IA : Configuration de canari en AWS","de":"KI-Tools: Einrichtung von Canary-Release in AWS","pt":"Ferramentas de IA: Configuração de Canary no AWS","ru":"ИИ Агенты: Настройка Canary в AWS","ar":"أدوات الذكاء الاصطناعي: إعداد Canary في AWS","en":"deployment-aws-canary-setup"},"description":{"zh":"此AI智能代理实现了无状态世界和有状态世界之间的桥接，例如Lambda和MQTT或Azure Service Bus","ja":"このAIエージェントは、ステートレスな世界とステートフルな世界の間のブリッジを提供します。例えば、LambdaとMQTTまたはAzure Service Bus","ko":"이 AI 에이전트는 무상태 세계와 상태FUL 세계 간의 브릿지를 제공합니다. 예를 들어, Lambda와 MQTT 또는 Azure Service Bus","es":"La configuración de canario en AWS es un puente entre el mundo sin estado y el estado, como Lambda y MQTT o Azure Service Bus, permitiendo una integración fl...","fr":"La configuration de canari en AWS est un pont entre le monde sans état et l''état, comme Lambda et MQTT ou Azure Service Bus, permettant une intégration fluide","de":"Die Canary-Release-Konfiguration in AWS ist eine Brücke zwischen der staatenlosen Welt und der staatenreichen Welt, wie Lambda und MQTT oder Azure Service Bu...","pt":"O deployment-aws-canary-setup é uma ponte entre o mundo stateless e stateful, permitindo a integração de serviços como Lambda e MQTT","ru":"Deployment-aws-canary-setup является мостом между бесстатным и статным мирами, позволяя интегрировать сервисы, такие как Lambda и MQTT","ar":"deployment-aws-canary-setup هو جسر بين العالم الخالي من الحالة وال世界 الحالم، مما يسمح بدمج خدمات مثل Lambda و MQTT","en":"This is a bridge between the stateless world and the stateful such as Lambda <-> MQTT or Azure Service Bus"},"definition":{"en":"This is a bridge between the stateless world and the stateful such as Lambda <-> MQTT or Azure Service Bus"},"features":{"zh":["实现Lambda和MQTT或Azure Service Bus之间的桥接","支持无状态和有状态系统之间的集成","提高部署效率和可靠性","提供可扩展和灵活的架构","支持多种编程语言和框架"],"ja":["LambdaとMQTTまたはAzure Service Busの間のブリッジを実現","ステートレスなシステムとステートフルなシステムの間の統合をサポート","デプロイの効率と信頼性を向上させる","スケーラブルで柔軟なアーキテクチャを提供","複数のプログラミング言語とフレームワークをサポート"],"ko":["Lambda와 MQTT 또는 Azure Service Bus 간의 브릿지를 구축","무상태 시스템과 상태FUL 시스템 간의 통합을 지원","배포 효율성과 안정성을 향상","확장 가능하고 유연한 아키텍처 제공","다수의 프로그래밍 언어와 프레임워크 지원"],"es":["Integración fluida entre Lambda y MQTT o Azure Service Bus","Implementación de configuración de canario en AWS","Conexión entre el mundo sin estado y el estado","Soporte para herramientas de AI","Facilidad de uso y configuración"],"fr":["Intégration fluide entre Lambda et MQTT ou Azure Service Bus","Mise en place d''une configuration de canari en AWS","Connexion entre le monde sans état et l''état","Prise en charge des outils d''IA","Facilité d''utilisation et de configuration"],"de":["Nahtlose Integration zwischen Lambda und MQTT oder Azure Service Bus","Einrichtung einer Canary-Release-Konfiguration in AWS","Verbindung zwischen der staatenlosen Welt und der staatenreichen Welt","Unterstützung für KI-Tools","Einfachheit bei der Verwendung und Konfiguration"],"pt":["Integração de serviços stateless e stateful","Suporte a Lambda e MQTT","Configuração de Canary para deploy","Integração com o ecossistema AWS","Suporte a desenvolvedores de aplicativos"],"ru":["Интеграция бесстатных и статных сервисов","Поддержка Lambda и MQTT","Настройка Canary для deploy","Интеграция с экосистемой AWS","Поддержка разработчиков приложений"],"ar":["دمج خدمات الخالية من الحالة والخدمات الحالمة","دعم Lambda و MQTT","إعداد Canary لتحديث التطبيق","دمج مع نظام البيئة AWS","دعم مطورين التطبيقات"]},"keywords":{"zh":["AI智能代理","部署AWS金丝雀发布","Lambda和MQTT集成","Azure Service Bus集成","无状态和有状态系统集成","如何使用AI智能代理","AI智能代理安装","AI智能代理设置指南"],"ja":["AIエージェント","AWSカナリアリリースの設定","LambdaとMQTTの統合","Azure Service Busの統合","ステートレスなシステムとステートフルなシステムの統合","AIエージェントの使用方法","AIエージェントのインストール","AIエージェントの設定ガイド"],"ko":["AI 에이전트","AWS 카나리 배포 설정","Lambda와 MQTT 통합","Azure Service Bus 통합","무상태 시스템과 상태FUL 시스템 통합","AI 에이전트 사용 방법","AI 에이전트 설치","AI 에이전트 설정 가이드"],"es":["herramientas de AI","configuración de canario en AWS","integración de Lambda y MQTT","Azure Service Bus","implementación de canario","herramientas de desarrollo de AI","guias de configuración de canario","alternativas a canario"],"fr":["outils d''IA","configuration de canari en AWS","intégration de Lambda et MQTT","Azure Service Bus","mise en place de canari","outils de développement d''IA","guides de configuration de canari","alternatives à canari"],"de":["KI-Tools","Einrichtung von Canary-Release in AWS","Integration von Lambda und MQTT","Azure Service Bus","Implementierung von Canary-Release","Entwicklertools für KI","Konfigurationsleitfäden für Canary-Release","Alternativen zu Canary-Release"],"pt":["ferramentas de ia","configuração de canary","deployment aws","integração de serviços","lambda e mqtt","guia de instalação","alternativas ao deployment-aws-canary-setup"],"ru":["ИИ агенты","настройка canary","deployment aws","интеграция сервисов","lambda и mqtt","руководство по установке","альтернативы deployment-aws-canary-setup"],"ar":["أدوات الذكاء الاصطناعي","إعداد كاناري","نشر aws","دمج الخدمات","لامدا و ام كيو تي","دليل التثبيت","بديل لبرنامج deployment-aws-canary-setup"]}},"owner":"mariotoffia","repo":"gobridge","repoPath":"mariotoffia/gobridge","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.689Z","topics":[],"category":"community","skillMd":{"name":"deployment-aws-canary-setup","description":"Step-by-step guide for setting up AWS Lambda canary deployments with CDK, CloudWatch alarms, and automated rollback.","bodyPreview":"# Skill: AWS Canary Deployment Setup\n\nThis skill teaches you how to set up progressive canary deployments for AWS Lambda using CDK TypeScript. You''ll configure Lambda versions and aliases, CloudWatch alarms for automated rollback, and CodeDeploy deployment groups for traffic shifting.\n\nCanary deployments reduce deployment risk by routing a small percentage of traffic to new code first. If the new version performs well (low errors, acceptable latency), traffic gradually shifts until 100% reaches","body":"# Skill: AWS Canary Deployment Setup\n\nThis skill teaches you how to set up progressive canary deployments for AWS Lambda using CDK TypeScript. You''ll configure Lambda versions and aliases, CloudWatch alarms for automated rollback, and CodeDeploy deployment groups for traffic shifting.\n\nCanary deployments reduce deployment risk by routing a small percentage of traffic to new code first. If the new version performs well (low errors, acceptable latency), traffic gradually shifts until 100% reaches the new version. If metrics fail, traffic automatically rolls back to the stable version.\n\nThis approach is essential for production workloads where zero-downtime deployments and automatic failure recovery are critical requirements.\n\n## Prerequisites\n\n- AWS CDK v2 installed (`npm install -g aws-cdk`)\n- TypeScript project with CDK configured\n- Lambda function deployed with proper IAM roles\n- CloudWatch configured for Lambda metrics\n- Understanding of Lambda versions and aliases\n\n## Overview\n\nIn this skill, you will:\n1. Create Lambda function with versioning and alias\n2. Configure CloudWatch alarms for error rate and latency\n3. Set up CodeDeploy deployment group with canary config\n4. Create CDK stack with all deployment infrastructure\n5. Implement rollback procedures\n6. Add monitoring dashboard for canary metrics\n\n## Step 1: Create Lambda with Versioning and Alias\n\nLambda versions are immutable snapshots of your function code and configuration. Aliases are mutable pointers that can route traffic between versions.\n\n### CDK Lambda Construct with Versioning\n\n```typescript\n// lib/constructs/versioned-lambda.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport { Construct } from ''constructs'';\n\nexport interface VersionedLambdaProps {\n  functionName: string;\n  description: string;\n  codePath: string;\n  handler: string;\n  runtime: lambda.Runtime;\n  memorySize?: number;\n  timeout?: cdk.Duration;\n  environment?: { [key: string]: string };\n  reservedConcurrentExecutions?: number;\n}\n\nexport class VersionedLambda extends Construct {\n  public readonly function: lambda.Function;\n  public readonly alias: lambda.Alias;\n  public readonly currentVersion: lambda.Version;\n\n  constructor(scope: Construct, id: string, props: VersionedLambdaProps) {\n    super(scope, id);\n\n    // Create Lambda function with tracing enabled\n    this.function = new lambda.Function(this, ''Function'', {\n      functionName: props.functionName,\n      description: props.description,\n      runtime: props.runtime,\n      handler: props.handler,\n      code: lambda.Code.fromAsset(props.codePath),\n      memorySize: props.memorySize ?? 256,\n      timeout: props.timeout ?? cdk.Duration.seconds(30),\n      environment: props.environment,\n      tracing: lambda.Tracing.ACTIVE,\n      reservedConcurrentExecutions: props.reservedConcurrentExecutions,\n      // Enable versioning by setting currentVersionOptions\n      currentVersionOptions: {\n        removalPolicy: cdk.RemovalPolicy.RETAIN,\n        description: `Version deployed at ${new Date().toISOString()}`,\n      },\n    });\n\n    // Get the current version (creates new version on each deployment)\n    this.currentVersion = this.function.currentVersion;\n\n    // Create alias pointing to current version\n    // The alias is what API Gateway or other services invoke\n    this.alias = new lambda.Alias(this, ''LiveAlias'', {\n      aliasName: ''live'',\n      version: this.currentVersion,\n      description: ''Production traffic alias'',\n    });\n  }\n}\n```\n\nThe key concepts here:\n- **Versions**: Each deployment creates an immutable version snapshot\n- **Alias**: The \"live\" alias is what clients invoke, not a specific version\n- **Traffic routing**: The alias can split traffic between two versions\n\n### Using the Construct\n\n```typescript\n// lib/stacks/api-stack.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\nimport { VersionedLambda } from ''../constructs/versioned-lambda'';\n\nexport class ApiStack extends cdk.Stack {\n  public readonly apiHandler: VersionedLambda;\n\n  constructor(scope: Construct, id: string, props?: cdk.StackProps) {\n    super(scope, id, props);\n\n    const stage = this.node.tryGetContext(''stage'') || ''dev'';\n\n    this.apiHandler = new VersionedLambda(this, ''ApiHandler'', {\n      functionName: `my-service-api-${stage}`,\n      description: ''API handler for my-service'',\n      codePath: ''../dist/api'',\n      handler: ''bootstrap'',\n      runtime: lambda.Runtime.PROVIDED_AL2023,\n      memorySize: 256,\n      timeout: cdk.Duration.seconds(30),\n      environment: {\n        STAGE: stage,\n        LOG_LEVEL: stage === ''prod'' ? ''INFO'' : ''DEBUG'',\n      },\n    });\n\n    // Export alias ARN for API Gateway integration\n    new cdk.CfnOutput(this, ''ApiAliasArn'', {\n      value: this.apiHandler.alias.functionArn,\n      description: ''Lambda alias ARN for API Gateway'',\n    });\n  }\n}\n```\n\n## Step 2: Configure CloudWatch Alarms\n\nCloudWatch alarms monitor your Lambda''s health during deployment. If metrics breach thresholds, CodeDeploy triggers automatic rollback.\n\n### Alarm Configuration Construct\n\n```typescript\n// lib/constructs/deployment-alarms.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\n\nexport interface DeploymentAlarmsProps {\n  lambdaFunction: lambda.Function;\n  alias: lambda.Alias;\n  alarmNamePrefix: string;\n  // Thresholds\n  errorRateThreshold?: number;      // Default: 1%\n  latencyP99Threshold?: number;     // Default: 5000ms\n  throttleThreshold?: number;       // Default: 10 per minute\n  evaluationPeriods?: number;       // Default: 2\n}\n\nexport class DeploymentAlarms extends Construct {\n  public readonly errorAlarm: cloudwatch.Alarm;\n  public readonly latencyAlarm: cloudwatch.Alarm;\n  public readonly throttleAlarm: cloudwatch.Alarm;\n  public readonly allAlarms: cloudwatch.Alarm[];\n\n  constructor(scope: Construct, id: string, props: DeploymentAlarmsProps) {\n    super(scope, id);\n\n    const evaluationPeriods = props.evaluationPeriods ?? 2;\n\n    // Error rate alarm - triggers rollback if errors exceed threshold\n    this.errorAlarm = new cloudwatch.Alarm(this, ''ErrorAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-errors`,\n      alarmDescription: ''Lambda error rate exceeded threshold during deployment'',\n      metric: props.alias.metricErrors({\n        period: cdk.Duration.minutes(1),\n        statistic: ''Sum'',\n      }),\n      threshold: props.errorRateThreshold ?? 10,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    // P99 latency alarm - triggers rollback if latency too high\n    this.latencyAlarm = new cloudwatch.Alarm(this, ''LatencyAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-latency-p99`,\n      alarmDescription: ''Lambda P99 latency exceeded threshold during deployment'',\n      metric: props.alias.metricDuration({\n        period: cdk.Duration.minutes(1),\n        statistic: ''p99'',\n      }),\n      threshold: props.latencyP99Threshold ?? 5000,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    // Throttle alarm - indicates capacity issues\n    this.throttleAlarm = new cloudwatch.Alarm(this, ''ThrottleAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-throttles`,\n      alarmDescription: ''Lambda throttling detected during deployment'',\n      metric: props.alias.metricThrottles({\n        period: cdk.Duration.minutes(1),\n        statistic: ''Sum'',\n      }),\n      threshold: props.throttleThreshold ?? 10,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    this.allAlarms = [this.errorAlarm, this.latencyAlarm, this.throttleAlarm];\n  }\n}\n```\n\nThese alarms monitor the alias (which receives production traffic), not the function directly. This ensures we''re measuring the actual user experience during canary deployment.\n\n## Step 3: Configure CodeDeploy Deployment Group\n\nCodeDeploy manages the traffic shifting between Lambda versions. It supports multiple deployment strategies.\n\n### Deployment Configuration Options\n\n```typescript\n// lib/constructs/canary-deployment.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport { Construct } from ''constructs'';\n\n// Available deployment configurations\nexport enum CanaryDeploymentConfig {\n  // Canary: Deploy to small percentage, wait, then 100%\n  CANARY_10_PERCENT_5_MINUTES = ''CANARY_10PERCENT_5MINUTES'',\n  CANARY_10_PERCENT_10_MINUTES = ''CANARY_10PERCENT_10MINUTES'',\n  CANARY_10_PERCENT_15_MINUTES = ''CANARY_10PERCENT_15MINUTES'',\n  \n  // Linear: Gradually increase traffic at fixed intervals\n  LINEAR_10_PERCENT_EVERY_1_MINUTE = ''LINEAR_10PERCENT_EVERY_1MINUTE'',\n  LINEAR_10_PERCENT_EVERY_2_MINUTES = ''LINEAR_10PERCENT_EVERY_2MINUTES'',\n  LINEAR_10_PERCENT_EVERY_3_MINUTES = ''LINEAR_10PERCENT_EVERY_3MINUTES'',\n  LINEAR_10_PERCENT_EVERY_10_MINUTES = ''LINEAR_10PERCENT_EVERY_10MINUTES'',\n  \n  // All at once (not recommended for production)\n  ALL_AT_ONCE = ''ALL_AT_ONCE'',\n}\n\nexport interface CanaryDeploymentProps {\n  alias: lambda.Alias;\n  deploymentConfig: CanaryDeploymentConfig;\n  alarms: cloudwatch.Alarm[];\n  applicationName?: string;\n  deploymentGroupName?: string;\n}\n\nexport class CanaryDeployment extends Construct {\n  public readonly application: codedeploy.LambdaApplication;\n  public readonly deploymentGroup: codedeploy.LambdaDeploymentGroup;\n\n  constructor(scope: Construct, id: string, props: CanaryDeploymentProps) {\n    super(scope, id);\n\n    // Create CodeDeploy application\n    this.application = new codedeploy.LambdaApplication(this, ''Application'', {\n      applicationName: props.applicationName,\n    });\n\n    // Map deployment config enum to CDK deployment config\n    const deploymentConfig = this.getDeploymentConfig(props.deploymentConfig);\n\n    // Create deployment group with automatic rollback\n    this.deploymentGroup = new codedeploy.LambdaDeploymentGroup(this, ''DeploymentGroup'', {\n      application: this.application,\n      deploymentGroupName: props.deploymentGroupName,\n      alias: props.alias,\n      deploymentConfig: deploymentConfig,\n      \n      // Attach alarms for automatic rollback\n      alarms: props.alarms,\n      \n      // Auto-rollback on deployment failure or alarm breach\n      autoRollback: {\n        failedDeployment: true,\n        stoppedDeployment: true,\n        deploymentInAlarm: true,\n      },\n    });\n  }\n\n  private getDeploymentConfig(\n    config: CanaryDeploymentConfig\n  ): codedeploy.ILambdaDeploymentConfig {\n    switch (config) {\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_5_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_5MINUTES;\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_10MINUTES;\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_15_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_15MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_1_MINUTE:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_1MINUTE;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_2_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_2MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_3_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_3MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_10_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_10MINUTES;\n      case CanaryDeploymentConfig.ALL_AT_ONCE:\n        return codedeploy.LambdaDeploymentConfig.ALL_AT_ONCE;\n      default:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_5MINUTES;\n    }\n  }\n}\n```\n\n### Deployment Config Comparison\n\n| Config | Traffic Shift | Total Time | Use Case |\n|--------|---------------|------------|----------|\n| CANARY_10PERCENT_5MINUTES | 10% → 100% | 5 min | Quick validation |\n| CANARY_10PERCENT_10MINUTES | 10% → 100% | 10 min | Standard production |\n| LINEAR_10PERCENT_EVERY_1MINUTE | 10% increments | 10 min | Gradual rollout |\n| LINEAR_10PERCENT_EVERY_10MINUTES | 10% increments | 100 min | High-risk changes |\n\n## Step 4: Complete CDK Stack\n\nCombine all components into a production-ready deployment stack.\n\n```typescript\n// lib/stacks/canary-deployment-stack.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport { Construct } from ''constructs'';\nimport { VersionedLambda } from ''../constructs/versioned-lambda'';\nimport { DeploymentAlarms } from ''../constructs/deployment-alarms'';\nimport { CanaryDeployment, CanaryDeploymentConfig } from ''../constructs/canary-deployment'';\n\nexport interface CanaryDeploymentStackProps extends cdk.StackProps {\n  stage: string;\n  serviceName: string;\n  codePath: string;\n  deploymentConfig?: CanaryDeploymentConfig;\n  errorRateThreshold?: number;\n  latencyP99Threshold?: number;\n}\n\nexport class CanaryDeploymentStack extends cdk.Stack {\n  public readonly lambdaFunction: lambda.Function;\n  public readonly alias: lambda.Alias;\n  public readonly deploymentGroup: codedeploy.LambdaDeploymentGroup;\n\n  constructor(scope: Construct, id: string, props: CanaryDeploymentStackProps) {\n    super(scope, id, props);\n\n    const alarmPrefix = `${props.serviceName}-${props.stage}`;\n\n    // Create versioned Lambda\n    const versionedLambda = new VersionedLambda(this, ''ApiHandler'', {\n      functionName: `${props.serviceName}-api-${props.stage}`,\n      description: `${props.serviceName} API handler`,\n      codePath: props.codePath,\n      handler: ''bootstrap'',\n      runtime: lambda.Runtime.PROVIDED_AL2023,\n      memorySize: 256,\n      timeout: cdk.Duration.seconds(30),\n      environment: {\n        STAGE: props.stage,\n        SERVICE_NAME: props.serviceName,\n      },\n    });\n\n    this.lambdaFunction = versionedLambda.function;\n    this.alias = versionedLambda.alias;\n\n    // Create deployment alarms\n    const alarms = new DeploymentAlarms(this, ''Alarms'', {\n      lambdaFunction: this.lambdaFunction,\n      alias: this.alias,\n      alarmNamePrefix: alarmPrefix,\n      errorRateThreshold: props.errorRateThreshold,\n      latencyP99Threshold: props.latencyP99Threshold,\n    });\n\n    // Determine deployment config based on stage\n    const deploymentConfig = props.deploymentConfig ?? \n      (props.stage === ''prod'' \n        ? CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES\n        : CanaryDeploymentConfig.ALL_AT_ONCE);\n\n    // Create canary deployment group\n    const canaryDeployment = new CanaryDeployment(this, ''CanaryDeploy'', {\n      alias: this.alias,\n      deploymentConfig: deploymentConfig,\n      alarms: alarms.allAlarms,\n      applicationName: `${props.serviceName}-${props.stage}`,\n      deploymentGroupName: `${props.serviceName}-${props.stage}-dg`,\n    });\n\n    this.deploymentGroup = canaryDeployment.deploymentGroup;\n\n    // Outputs\n    new cdk.CfnOutput(this, ''FunctionName'', {\n      value: this.lambdaFunction.functionName,\n    });\n\n    new cdk.CfnOutput(this, ''AliasArn'', {\n      value: this.alias.functionArn,\n    });\n\n    new cdk.CfnOutput(this, ''CurrentVersion'', {\n      value: versionedLambda.currentVersion.version,\n    });\n\n    new cdk.CfnOutput(this, ''DeploymentGroupName'', {\n      value: this.deploymentGroup.deploymentGroupName,\n    });\n  }\n}\n```\n\n### CDK App Entry Point\n\n```typescript\n// bin/app.ts\n#!/usr/bin/env node\nimport ''source-map-support/register'';\nimport * as cdk from ''aws-cdk-lib'';\nimport { CanaryDeploymentStack } from ''../lib/stacks/canary-deployment-stack'';\nimport { CanaryDeploymentConfig } from ''../lib/constructs/canary-deployment'';\n\nconst app = new cdk.App();\n\nconst stage = app.node.tryGetContext(''stage'') || ''dev'';\nconst serviceName = ''my-service'';\n\nnew CanaryDeploymentStack(app, `${serviceName}-${stage}`, {\n  stage: stage,\n  serviceName: serviceName,\n  codePath: ''../dist/api'',\n  deploymentConfig: stage === ''prod'' \n    ? CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES\n    : CanaryDeploymentConfig.ALL_AT_ONCE,\n  errorRateThreshold: 10,\n  latencyP99Threshold: 5000,\n  env: {\n    account: process.env.CDK_DEFAULT_ACCOUNT,\n    region: process.env.CDK_DEFAULT_REGION || ''eu-west-1'',\n  },\n});\n```\n\n## Step 5: Test Rollback Scenarios\n\nImplement scripts and procedures for testing rollback behavior.\n\n### Metrics Check Script\n\n```bash\n#!/bin/bash\n# scripts/check-metrics.sh\n# Validates Lambda metrics for canary deployment health\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nFUNCTION_NAME=\"${SERVICE}-api-${STAGE}\"\nALIAS_NAME=\"live\"\n\necho \"Checking metrics for ${FUNCTION_NAME}:${ALIAS_NAME}...\"\n\n# Time range: last 5 minutes\nEND_TIME=$(date -u +\"%Y-%m-%dT%H:%M:%SZ\")\nSTART_TIME=$(date -u -v-5M +\"%Y-%m-%dT%H:%M:%SZ\" 2>/dev/null || \\\n             date -u -d \"5 minutes ago\" +\"%Y-%m-%dT%H:%M:%SZ\")\n\n# Get error count\nERRORS=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Errors \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --statistics Sum \\\n  --query ''Datapoints[0].Sum'' \\\n  --output text 2>/dev/null || echo \"0\")\n\n# Get invocation count  \nINVOCATIONS=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Invocations \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --statistics Sum \\\n  --query ''Datapoints[0].Sum'' \\\n  --output text 2>/dev/null || echo \"1\")\n\n# Get P99 duration\nDURATION_P99=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Duration \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --extended-statistics p99 \\\n  --query ''Datapoints[0].ExtendedStatistics.p99'' \\\n  --output text 2>/dev/null || echo \"0\")\n\n# Handle None values\nERRORS=${ERRORS//None/0}\nINVOCATIONS=${INVOCATIONS//None/1}\nDURATION_P99=${DURATION_P99//None/0}\n\n# Calculate error rate\nif [[ \"$INVOCATIONS\" != \"0\" ]]; then\n  ERROR_RATE=$(echo \"scale=4; $ERRORS / $INVOCATIONS\" | bc)\nelse\n  ERROR_RATE=\"0\"\nfi\n\necho \"==========================================\"\necho \"Errors:       $ERRORS\"\necho \"Invocations:  $INVOCATIONS\"\necho \"Error Rate:   $ERROR_RATE\"\necho \"P99 Duration: ${DURATION_P99}ms\"\necho \"==========================================\"\n\n# Validate against thresholds\nFAILED=0\n\nif (( $(echo \"$ERROR_RATE > 0.01\" | bc -l) )); then\n  echo \"❌ FAIL: Error rate $ERROR_RATE > 1%\"\n  FAILED=1\nfi\n\nif (( $(echo \"$DURATION_P99 > 5000\" | bc -l) )); then\n  echo \"❌ FAIL: P99 latency ${DURATION_P99}ms > 5000ms\"\n  FAILED=1\nfi\n\nif [[ $FAILED -eq 1 ]]; then\n  echo \"\"\n  echo \"Metrics validation FAILED - rollback recommended\"\n  exit 1\nfi\n\necho \"✅ PASS: All metrics within thresholds\"\nexit 0\n```\n\n### Manual Rollback Commands\n\n```bash\n#!/bin/bash\n# scripts/rollback.sh\n# Manually rollback to previous Lambda version\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nFUNCTION_NAME=\"${SERVICE}-api-${STAGE}\"\nALIAS_NAME=\"live\"\n\necho \"Rolling back ${FUNCTION_NAME}...\"\n\n# Get previous version (second to last)\nPREVIOUS_VERSION=$(aws lambda list-versions-by-function \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --query ''Versions[-2].Version'' \\\n  --output text)\n\nif [[ \"$PREVIOUS_VERSION\" == \"None\" || \"$PREVIOUS_VERSION\" == \"\\$LATEST\" ]]; then\n  echo \"Error: No previous version found to rollback to\"\n  exit 1\nfi\n\necho \"Rolling back to version: $PREVIOUS_VERSION\"\n\n# Update alias to point to previous version (100% traffic)\naws lambda update-alias \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --name \"$ALIAS_NAME\" \\\n  --function-version \"$PREVIOUS_VERSION\" \\\n  --routing-config ''AdditionalVersionWeights={}''\n\necho \"✅ Rollback complete. Alias now points to version $PREVIOUS_VERSION\"\n\n# Verify\nCURRENT=$(aws lambda get-alias \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --name \"$ALIAS_NAME\" \\\n  --query ''FunctionVersion'' \\\n  --output text)\n\necho \"Current alias version: $CURRENT\"\n```\n\n### Stop In-Progress Deployment\n\n```bash\n#!/bin/bash\n# scripts/stop-deployment.sh\n# Stop an in-progress CodeDeploy deployment\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nAPPLICATION_NAME=\"${SERVICE}-${STAGE}\"\nDEPLOYMENT_GROUP=\"${SERVICE}-${STAGE}-dg\"\n\n# Get current deployment ID\nDEPLOYMENT_ID=$(aws deploy list-deployments \\\n  --application-name \"$APPLICATION_NAME\" \\\n  --deployment-group-name \"$DEPLOYMENT_GROUP\" \\\n  --include-only-statuses \"InProgress\" \\\n  --query ''deployments[0]'' \\\n  --output text)\n\nif [[ \"$DEPLOYMENT_ID\" == \"None\" ]]; then\n  echo \"No in-progress deployment found\"\n  exit 0\nfi\n\necho \"Stopping deployment: $DEPLOYMENT_ID\"\n\naws deploy stop-deployment \\\n  --deployment-id \"$DEPLOYMENT_ID\" \\\n  --auto-rollback-enabled\n\necho \"✅ Deployment stopped and rollback initiated\"\n```\n\n## Step 6: Monitor Canary Metrics\n\nCreate a CloudWatch dashboard for monitoring canary deployments in real-time.\n\n```typescript\n// lib/constructs/canary-dashboard.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\n\nexport interface CanaryDashboardProps {\n  dashboardName: string;\n  lambdaFunction: lambda.Function;\n  alias: lambda.Alias;\n}\n\nexport class CanaryDashboard extends Construct {\n  public readonly dashboard: cloudwatch.Dashboard;\n\n  constructor(scope: Construct, id: string, props: CanaryDashboardProps) {\n    super(scope, id);\n\n    this.dashboard = new cloudwatch.Dashboard(this, ''Dashboard'', {\n      dashboardName: props.dashboardName,\n    });\n\n    // Error rate widget\n    this.dashboard.addWidgets(\n      new cloudwatch.GraphWidget({\n        title: ''Error Rate'',\n        left: [\n          props.alias.metricErrors({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n            label: ''Errors'',\n          }),\n        ],\n        right: [\n          props.alias.metricInvocations({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n            label: ''Invocations'',\n          }),\n        ],\n        width: 12,\n      }),\n      new cloudwatch.GraphWidget({\n        title: ''Latency (P50, P90, P99)'',\n        left: [\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p50'',\n            label: ''P50'',\n          }),\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p90'',\n            label: ''P90'',\n          }),\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p99'',\n            label: ''P99'',\n          }),\n        ],\n        width: 12,\n      })\n    );\n\n    // Throttles and concurrent executions\n    this.dashboard.addWidgets(\n      new cloudwatch.GraphWidget({\n        title: ''Throttles'',\n        left: [\n          props.alias.metricThrottles({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n          }),\n        ],\n        width: 8,\n      }),\n      new cloudwatch.GraphWidget({\n        title: ''Concurrent Executions'',\n        left: [\n          props.lambdaFunction.metric(''ConcurrentExecutions'', {\n            period: cdk.Duration.minutes(1),\n            statistic: ''Maximum'',\n          }),\n        ],\n        width: 8,\n      }),\n      new cloudwatch.SingleValueWidget({\n        title: ''Current Error Rate'',\n        metrics: [\n          props.alias.metricErrors({\n            period: cdk.Duration.minutes(5),\n            statistic: ''Sum'',\n          }),\n        ],\n        width: 8,\n      })\n    );\n  }\n}\n```\n\n## Makefile Targets\n\nAdd deployment targets to your Makefile for easy canary operations.\n\n```makefile\n# Makefile for canary deployment operations\n\nSERVICE_NAME := my-service\nSTAGE ?= dev\nCDK_DIR := deploy/cdk\nVERSION ?= $(shell git describe --tags --always)\n\n.PHONY: deploy deploy-canary promote rollback check-metrics stop-deployment\n\n# Standard deployment (uses stage-appropriate config)\ndeploy: build\n\t@echo \"Deploying $(SERVICE_NAME) to $(STAGE)...\"\n\tcd $(CDK_DIR) && cdk deploy --context stage=$(STAGE) --require-approval never\n\n# Deploy with specific canary weight (0.1 = 10%, 0.5 = 50%)\ndeploy-canary: build\nifndef WEIGHT\n\t$(error WEIGHT is required, e.g., make deploy-canary WEIGHT=0.1)\nendif\n\t@echo \"Deploying canary at $(WEIGHT) weight...\"\n\tcd $(CDK_DIR) && CANARY_WEIGHT=$(WEIGHT) cdk deploy --context stage=$(STAGE)\n\n# Promote canary to 100%\npromote:\n\t@echo \"Promoting $(SERVICE_NAME) to 100% in $(STAGE)...\"\n\t./scripts/promote.sh $(SERVICE_NAME) $(STAGE)\n\n# Rollback to previous version\nrollback:\n\t@echo \"Rolling back $(SERVICE_NAME) in $(STAGE)...\"\n\t./scripts/rollback.sh $(SERVICE_NAME) $(STAGE)\n\n# Check deployment metrics\ncheck-metrics:\n\t@./scripts/check-metrics.sh $(SERVICE_NAME) $(STAGE)\n\n# Stop in-progress deployment\nstop-deployment:\n\t@./scripts/stop-deployment.sh $(SERVICE_NAME) $(STAGE)\n\n# Build Lambda binary\nbuild:\n\tGOOS=linux GOARCH=arm64 CGO_ENABLED=0 go build -o bootstrap ./cmd/api\n\tzip -j dist/api.zip bootstrap\n\trm bootstrap\n```\n\n## Verification Checklist\n\nAfter setting up canary deployments, verify:\n\n- [ ] Lambda function publishes new version on each deployment\n- [ ] Alias \"live\" exists and points to current version\n- [ ] CloudWatch alarms configured for errors, latency, and throttles\n- [ ] CodeDeploy deployment group created with correct config\n- [ ] Alarms attached to deployment group for auto-rollback\n- [ ] autoRollback enabled for failedDeployment and deploymentInAlarm\n- [ ] Metrics check script validates error rate < 1%\n- [ ] Metrics check script validates P99 latency < 5000ms\n- [ ] Manual rollback script updates alias to previous version\n- [ ] Stop deployment script halts in-progress deployments\n- [ ] Dashboard shows real-time canary metrics\n- [ ] Makefile has deploy, rollback, and check-metrics targets\n- [ ] Different deployment configs used per environment (ALL_AT_ONCE for dev, CANARY for prod)\n"},"lastSynced":"2026-03-04T13:30:57.790Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing advanced AWS Lambda deployment strategies, particularly those leveraging CDK TypeScript for canary releases.","zh":"适合需要高级AWS Lambda部署策略的Cloud Agents，特别是那些利用CDK TypeScript进行金丝雀发布的场景。","ja":"AWS Lambdaの高度なデプロイ戦略を必要とするCloud Agentsに適しています。特に、CDK TypeScriptを使用したカナリアリリースを利用する場合に効果的です。","ko":"고급 AWS Lambda 배포 전략이 필요한 Cloud Agents에 적합합니다. 특히 CDK TypeScript를 사용한 카나리 배포를 활용하는 경우에 효과적입니다.","es":"Perfecto para agentes de Cloud que necesitan estrategias de implementación avanzadas de AWS Lambda, particularmente aquellos que aprovechan CDK TypeScript para lanzamientos de canario.","fr":"Parfait pour les agents Cloud ayant besoin de stratégies de déploiement avancées AWS Lambda, en particulier ceux qui utilisent CDK TypeScript pour les versions de canari.","de":" Perfekt für Cloud-Agents, die erweiterte AWS Lambda-Bereitstellungsstrategien benötigen, insbesondere solche, die CDK TypeScript für Canary-Veröffentlichungen nutzen.","pt":"Perfeito para Agentes de Nuvem que necessitam de estratégias avançadas de deploy do AWS Lambda, particularmente aqueles que utilizam CDK TypeScript para lançamentos canários.","ru":"Идеально для облачных агентов, которым необходимы продвинутые стратегии развертывания AWS Lambda, особенно тех, кто использует CDK TypeScript для канареечных выпусков.","ar":"مثالي لعميل السحابة الذين يحتاجون إلى استراتيجيات متقدمة لنشر AWS Lambda، خاصة أولئك الذين يستخدمون CDK TypeScript لنشرات الكناري."},"recommendation":{"en":"Empowers agents to orchestrate progressive canary deployments for AWS Lambda using CDK TypeScript, configuring Lambda versions and aliases, CloudWatch alarms for automated rollback, and CodeDeploy deployment groups for traffic shifting, thereby reducing deployment risk with protocols like MQTT.","zh":"使代理能够编排使用CDK TypeScript的AWS Lambda进行渐进式金丝雀部署，配置Lambda版本和别名，CloudWatch警报用于自动回滚，以及CodeDeploy部署组用于流量转移，从而使用MQTT等协议减少部署风险。","ja":"エージェントがCDK TypeScriptを使用したAWS Lambdaのカナリアリリースを段階的に進行させることを可能にします。Lambdaのバージョンとエイリアスを設定し、CloudWatchアラームによる自動ロールバックを行い、CodeDeployのデプロイグループによるトラフィックシフトを行うことで、MQTTなどのプロトコルを使用してデプロイリスクを軽減します。","ko":"에이전트가 CDK TypeScript를 사용하여 AWS Lambda의 카나리 배포를 점진적으로 진행할 수 있도록 합니다. 람다 버전 및 별칭을 구성하고 CloudWatch 경보를 사용한 자동 롤백 및 CodeDeploy 배포 그룹을 사용한 트래픽 전환을 통해 MQTT와 같은 프로토콜을 사용하여 배포 위험을 줄입니다.","es":"Permite a los agentes orquestar implementaciones de canari progresivas para AWS Lambda utilizando CDK TypeScript, configurando versiones y alias de Lambda, alarmas de CloudWatch para reversión automática y grupos de implementación de CodeDeploy para cambio de tráfico, reduciendo así el riesgo de implementación con protocolos como MQTT.","fr":"Permet aux agents d''orchestrer des déploiements de canari progressifs pour AWS Lambda à l''aide de CDK TypeScript, en configurant les versions et les alias Lambda, les alarmes CloudWatch pour une réversibilité automatique et les groupes de déploiement CodeDeploy pour le changement de trafic, réduisant ainsi le risque de déploiement avec des protocoles comme MQTT.","de":"Ermöglich es den Agenten, progressive Canary-Bereitstellungen für AWS Lambda mit CDK TypeScript zu orchestrieren, indem Lambda-Versionen und -Alias konfiguriert, CloudWatch-Alarmanlagen für automatisches Rückgängig machen und CodeDeploy-Bereitstellungsgruppen für Verkehrsumschaltung eingerichtet werden, wodurch das Bereitstellungsrisiko mit Protokollen wie MQTT reduziert wird.","pt":"Habilita os agentes a orquestrar lançamentos canários progressivos para AWS Lambda usando CDK TypeScript, configurando versões e alias do Lambda, alarmes do CloudWatch para rollback automatizado, e grupos de deploy do CodeDeploy para mudança de tráfego, reduzindo assim o risco de deploy com protocolos como MQTT.","ru":"Позволяет агентам оркестрировать постепенные канареечные развертывания для AWS Lambda с помощью CDK TypeScript, настраивая версии и псевдонимы Lambda, сигналы тревоги CloudWatch для автоматического отката, и группы развертывания CodeDeploy для переключения трафика, тем самым снижая риск развертывания с помощью протоколов như MQTT.","ar":"تمكين الوكلاء من تنسيق عمليات نشر الكناري التدريجي لآي إس إم إس لامبدا باستخدام سي دي كي تايب سكريبت، وتكوين إصدارات وأسماء مستعارة لامبدا، وإشعارات الحذر من كلاود ووتش للتراجع التلقائي، ومجموعات نشر كود ديبلي لمحول حركة المرور، وبالتالي خفض مخاطر النشر بروتوكولات مثل إم كيو تي تي."},"useCases":{"en":["Automating rollback procedures based on CloudWatch alarms for AWS Lambda functions","Configuring traffic shifting for canary deployments using CodeDeploy deployment groups","Setting up Lambda versions and aliases for controlled testing and deployment"],"zh":["基于CloudWatch警报为AWS Lambda函数自动化回滚程序","使用CodeDeploy部署组为金丝雀部署配置流量转移","设置Lambda版本和别名用于受控测试和部署"],"ja":["CloudWatchアラームを使用したAWS Lambda関数の自動ロールバック手順の自動化","CodeDeployデプロイグループを使用したカナリアリリースのトラフィックシフトの構成","Lambdaのバージョンとエイリアスの設定によるコントロールされたテストとデプロイ"],"ko":["CloudWatch 경보를 사용하여 AWS Lambda 함수의 자동 롤백 절차 자동화","CodeDeploy 배포 그룹을 사용하여 카나리 배포의 트래픽 전환 구성","람다 버전 및 별칭 설정을 통한 제어된 테스트 및 배포"],"es":["Automatizar procedimientos de reversión en función de alarmas de CloudWatch para funciones de AWS Lambda","Configurar el cambio de tráfico para implementaciones de canari utilizando grupos de implementación de CodeDeploy","Configurar versiones y alias de Lambda para pruebas y implementación controladas"],"fr":["Automatiser les procédures de réversibilité en fonction des alarmes CloudWatch pour les fonctions AWS Lambda","Configurer le changement de trafic pour les déploiements de canari à l''aide de groupes de déploiement CodeDeploy","Configurer les versions et les alias Lambda pour des tests et des déploiements contrôlés"],"de":["Automatisieren Sie die Rückgängig-Machungsverfahren auf der Grundlage von CloudWatch-Alarmanlagen für AWS Lambda-Funktionen","Konfigurieren Sie den Verkehrsumschaltung für Canary-Bereitstellungen mithilfe von CodeDeploy-Bereitstellungsgruppen","Konfigurieren Sie Lambda-Versionen und -Alias für kontrolliertes Testen und Bereitstellen"],"pt":["Automatizar procedimentos de rollback com base em alarmes do CloudWatch para funções do AWS Lambda","Configurar mudança de tráfego para lançamentos canários usando grupos de deploy do CodeDeploy","Configurar versões e alias do Lambda para testes e deploy controlados"],"ru":["Автоматизировать процедуры отката на основе сигналов тревоги CloudWatch для функций AWS Lambda","Настроить переключение трафика для канареечных выпусков с помощью групп развертывания CodeDeploy","Настроить версии и псевдонимы Lambda для контролируемого тестирования и развертывания"],"ar":["تأتمتة إجراءات التراجع بناءً على إشعارات الحذر من كلاود ووتش لأي إس إم إس لامبدا","تكوين تبديل حركة المرور لنشرات الكناري باستخدام مجموعات نشر كود ديبلي","تكوين إصدارات وأسماء مستعارة لامبدا لاختبارات ونشر محكمة"]},"limitations":{"en":["Requires AWS account with Lambda and CloudWatch access","CDK TypeScript knowledge necessary for effective use","Limited to AWS ecosystem, specifically Lambda and CodeDeploy services"],"zh":["需要具有Lambda和CloudWatch访问权限的AWS账户","需要CDK TypeScript知识以有效使用","仅限于AWS生态系统，特别是Lambda和CodeDeploy服务"],"ja":["LambdaおよびCloudWatchへのアクセス権を持つAWSアカウントが必要","有効に使用するにはCDK TypeScriptの知識が必要","AWSエコシステムのみに限定され、特にLambdaおよびCodeDeployサービス"],"ko":["람다 및 CloudWatch 액세스 권한이 있는 AWS 계정이 필요합니다.","유효하게 사용하려면 CDK TypeScript 지식이 필요합니다.","AWS 생태계에만 제한되며, 특히 람다 및 CodeDeploy 서비스"],"es":["Requiere una cuenta de AWS con acceso a Lambda y CloudWatch","Conocimiento de CDK TypeScript necesario para un uso efectivo","Limitado al ecosistema de AWS, específicamente a los servicios Lambda y CodeDeploy"],"fr":["Nécessite un compte AWS avec un accès à Lambda et CloudWatch","Connaissances de CDK TypeScript nécessaires pour une utilisation efficace","Limité à l''écosystème AWS, en particulier aux services Lambda et CodeDeploy"],"de":["Benötigt ein AWS-Konto mit Zugriff auf Lambda und CloudWatch","CDK-TypeScript-Kenntnisse sind für eine effektive Nutzung erforderlich","Begrenzt auf das AWS-Ökosystem, speziell auf die Dienste Lambda und CodeDeploy"],"pt":["Requer conta da AWS com acesso ao Lambda e CloudWatch","Conhecimento de CDK TypeScript necessário para uso eficaz","Limitado ao ecossistema da AWS, especificamente aos serviços Lambda e CodeDeploy"],"ru":["Требуется учетная запись AWS с доступом к Lambda и CloudWatch","Знание CDK TypeScript необходимо для эффективного использования","Ограничен экосистемой AWS, в частности сервисами Lambda и CodeDeploy"],"ar":["يتطلب حساب آي إس إم إس مع حق الوصول إلى لامبدا وكلاود ووتش","معرفة سي دي كي تايب سكريبت ضرورية للاستخدام الفعال","محدود ببيئة آي إس إم إس، تحديداً خدمات لامبدا وكود ديبلي"]},"version":3},"contentHash":"bf13ba527ac817430840b0c5588dc5da775c8b352f11c3eedea70def1c1fdc7a","qualityScore":42}');
DELETE FROM skills_fts WHERE id = 'mariotoffia/gobridge/deployment-aws-canary-setup';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mariotoffia/gobridge/deployment-aws-canary-setup', 'deployment-aws-canary-setup', 'mariotoffia', 'gobridge', 'community', 'deployment-aws-canary-setup mariotoffia gobridge community 此AI智能代理实现了无状态世界和有状态世界之间的桥接，例如Lambda和MQTT或Azure Service Bus このAIエージェントは、ステートレスな世界とステートフルな世界の間のブリッジを提供します。例えば、LambdaとMQTTまたはAzure Service Bus 이 AI 에이전트는 무상태 세계와 상태FUL 세계 간의 브릿지를 제공합니다. 예를 들어, Lambda와 MQTT 또는 Azure Service Bus La configuración de canario en AWS es un puente entre el mundo sin estado y el estado, como Lambda y MQTT o Azure Service Bus, permitiendo una integración fluida La configuration de canari en AWS est un pont entre le monde sans état et l''état, comme Lambda et MQTT ou Azure Service Bus, permettant une intégration fluide Die Canary-Release-Konfiguration in AWS ist eine Brücke zwischen der staatenlosen Welt und der staatenreichen Welt, wie Lambda und MQTT oder Azure Service Bus, und ermöglicht eine nahtlose Integration O deployment-aws-canary-setup é uma ponte entre o mundo stateless e stateful, permitindo a integração de serviços como Lambda e MQTT Deployment-aws-canary-setup является мостом между бесстатным и статным мирами, позволяя интегрировать сервисы, такие как Lambda и MQTT deployment-aws-canary-setup هو جسر بين العالم الخالي من الحالة وال世界 الحالم، مما يسمح بدمج خدمات مثل Lambda و MQTT This is a bridge between the stateless world and the stateful such as Lambda <-> MQTT or Azure Service Bus AI智能代理 部署AWS金丝雀发布 Lambda和MQTT集成 Azure Service Bus集成 无状态和有状态系统集成 如何使用AI智能代理 AI智能代理安装 AI智能代理设置指南 This is a bridge between the stateless world and the stateful such as Lambda <-> MQTT or Azure Service Bus');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sandervw/CorpLore/literary-revision', 'community', 'sandervw', 'CorpLore', 'sandervw/CorpLore', 'literary-revision', 0, 0, 42, '2026-03-04T13:07:01.689Z', '2026-03-04T13:31:02.032Z', '65f2abad20b84f65a3240ece6a92b3733ed3047f2204805fdbad152e75bfd677', '{"id":"sandervw/CorpLore/literary-revision","name":"literary-revision","description":{"zh":"文学修订AI智能工具用于构建CorpLore虚构场景的故事文档和代码","ja":"文学的修正AIエージェントは、CorpLoreフィクション設定のストーリー文書とコードを構築するために使用されます","ko":"문학 수정 AI 도구는 CorpLore 가상 세계 설정의 스토리 문서와 코드를 구축하는 데 사용됩니다","es":"La revisión literaria es una habilidad de agente AI que ayuda a construir historias y documentos en el entorno de ficción CorpLore","fr":"La révision littéraire est une compétence d''agent IA qui aide à construire des histoires et des documents dans l''environnement de fiction CorpLore","de":"Die literarische Revision ist eine Fähigkeit des KI-Agents, die dabei hilft, Geschichten und Dokumente in der CorpLore-Fiktionsumgebung zu erstellen","pt":"A habilidade literary-revision é uma ferramenta de IA que ajuda desenvolvedores a criar histórias e documentar código para o ambiente de ficção CorpLore","ru":"ИИ Агент literary-revision - это инструмент, который помогает разработчикам создавать истории и документировать код для CorpLore","ar":"مهارة literary-revision هي أداة ذكاء اصطناعي تساعد المطورين على إنشاء القصص وتوثيق الشفرة للبيئة الخيالية CorpLore","en":"Story building documents and code for the CorpLore fiction setting."},"seo":{"title":{"zh":"AI智能工具：文学修订（literary-revision）","ja":"AIエージェント：文学的修正（literary-revision）","ko":"AI 도구: 문학 수정(literary-revision)","es":"Herramientas AI para revisión literaria en CorpLore","fr":"Outils IA pour révision littéraire dans CorpLore","de":"KI-Tools für literarische Revision in CorpLore","pt":"Ferramentas de IA: literary-revision para Desenvolvedores","ru":"ИИ Агенты: