INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sandervw/CorpLore/literary-revision', 'literary-revision', 'sandervw', 'CorpLore', 'community', 'literary-revision sandervw CorpLore community 文学修订AI智能工具用于构建CorpLore虚构场景的故事文档和代码 文学的修正AIエージェントは、CorpLoreフィクション設定のストーリー文書とコードを構築するために使用されます 문학 수정 AI 도구는 CorpLore 가상 세계 설정의 스토리 문서와 코드를 구축하는 데 사용됩니다 La revisión literaria es una habilidad de agente AI que ayuda a construir historias y documentos en el entorno de ficción CorpLore La révision littéraire est une compétence d''agent IA qui aide à construire des histoires et des documents dans l''environnement de fiction CorpLore Die literarische Revision ist eine Fähigkeit des KI-Agents, die dabei hilft, Geschichten und Dokumente in der CorpLore-Fiktionsumgebung zu erstellen A habilidade literary-revision é uma ferramenta de IA que ajuda desenvolvedores a criar histórias e documentar código para o ambiente de ficção CorpLore ИИ Агент literary-revision - это инструмент, который помогает разработчикам создавать истории и документировать код для CorpLore مهارة literary-revision هي أداة ذكاء اصطناعي تساعد المطورين على إنشاء القصص وتوثيق الشفرة للبيئة الخيالية CorpLore Story building documents and code for the CorpLore fiction setting. 如何使用AI智能工具进行文学修订 什么是文学修订AI智能工具 CorpLore虚构场景设置 AI智能工具安装 AI智能工具设置指南 文学修订AI智能工具替代品 文学修订AI智能工具与竞争对手的比较 Story building documents and code for the CorpLore fiction setting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mr-karan/logchef/logchef', 'community', 'mr-karan', 'logchef', 'mr-karan/logchef', 'logchef', 0, 0, 42, '2026-03-04T13:07:01.704Z', '2026-03-04T13:41:50.685Z', 'c106a0a40d625cd7a24d5133239f6ac0c4c15e9b44c166ecca4f29a8b85354ef', '{"id":"mr-karan/logchef/logchef","name":"logchef","description":{"zh":"logchef是一款轻量级的单二进制日志分析界面，专注于ClickHouse高性能查询和可视化","ja":"logchefはClickHouseの高性能ログ分析と可視化に特化した軽量のシングルバイナリインターフェースです","ko":"logchef는 클릭하우스의 고성능 로그 분석 및 시각화를 위한 경량의 단일 바이너리 인터페이스입니다","es":"logchef es una interfaz de análisis de registros ligera y de alto rendimiento para ClickHouse, enfocada en consultas y visualizaciones rápidas","fr":"logchef est une interface d''analyse de logs légère et haute performance pour ClickHouse, axée sur des requêtes et des visualisations rapides","de":"logchef ist ein leichtes und leistungsfähiges Log-Analytics-Interface für ClickHouse, das auf schnelle Abfragen und Visualisierungen ausgerichtet ist","pt":"O logchef é uma interface de análise de logs leve e de alto desempenho para ClickHouse, focada em consultas e visualização de alta performance","ru":"logchef - это легкий и высокопроизводительный интерфейс анализа логов для ClickHouse, ориентированный на высокопроизводительные запросы и визуализацию","ar":"logchef هو واجهة تحليل سجلات خفيفة وعالية الأداء لClickHouse، تركز على استفسارات وتصوير عالية الأداء","en":"Lightweight, single-binary log analytics interface for ClickHouse, focused on high-performance querying and visualization"},"seo":{"title":{"zh":"logchef：AI工具，ClickHouse高性能日志分析","ja":"logchef：AIエージェントによるClickHouse高性能ログ分析","ko":"logchef: AI 에이전트, 클릭하우스 고성능 로그 분석","es":"Herramientas de logchef: Interfaz de análisis de registro...","fr":"Outils logchef: Interface d''analyse de logs légère pour C...","de":"Logchef-Tools: Leichtes Log-Analytics-Interface für Click...","pt":"Ferramen