INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EpicenterHQ/epicenter/documentation', 'documentation', 'EpicenterHQ', 'epicenter', 'community', 'documentation EpicenterHQ epicenter community AI智能文档工具，通过语音输入获取文本，免费开源，支持本地优先应用 AIエージェントドキュメントは、ショートカットを押して話してテキストを取得する、無料でオープンソースのツールです AI 에이전트 문서화 도구는 단축키를 눌러 말한 후 텍스트를 얻을 수 있는 무료 및 오픈 소스 도구입니다 La documentación se vuelve fácil con atajos y herramientas de AI de código abierto. Obtén texto con solo hablar La documentation devient facile avec des raccourcis et des outils d''IA open source. Obtenir du texte en parlant simplement Dokumentation wird einfach mit Shortcuts und Open-Source-KI-Tools. Erhalten Sie Text, indem Sie einfach sprechen A documentação de agente de IA é uma ferramenta gratuita e de código aberto que permite aos desenvolvedores criar aplicativos locais com facilidade Документация ИИ Агентов - это бесплатный и открытый инструмент, который позволяет разработчикам создавать местные приложения легко توثيق وثائق الوسائط هو أداة مجانية ومفتوحة المصدر تسمح للمطورين إنشاء تطبيقات محلية بسهولة Press shortcut → speak → get text. Free and open source. More local-first apps soon ❤️ AI智能文档工具 语音输入 免费开源 本地优先应用 如何使用AI文档工具 AI文档工具替代品 AI文档工具安装 AI文档工具设置指南 Press shortcut → speak → get text. Free and open source. More local-first apps soon ❤️');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thesampaton/durable-streams-reference/m13-domain-error', 'community', 'thesampaton', 'durable-streams-reference', 'thesampaton/durable-streams-reference', 'm13-domain-error', 0, 0, 42, '2026-03-04T13:07:01.714Z', '2026-03-04T13:46:33.767Z', '5e87ba8162af9e34e6a6afe6f50e7e708bc5363216f7d691870d25965cafa1d3', '{"id":"thesampaton/durable-streams-reference/m13-domain-error","name":"m13-domain-error","description":{"zh":"m13-domain-error是一个使用axum和tokio的Rust实现的Durable Streams协议，支持流读取、生产者幂等性、JSON批处理和TTL","ja":"m13-domain-errorは、axumとtokioを使用したRustによるDurable Streamsプロトコルの実装です。ストリーミング読み取り、プロデューサーの冪等性、JSONバッチモード、TTLをサポートします","ko":"m13-domain-error는 axum과 tokio를 사용하여 Rust로 구현된 Durable Streams 프로토콜로, 스트리밍 읽기, 생산자 동등성, JSON 배치 모드, TTL을 지원합니다","es":"m13-domain-error es una implementación de referencia de Durable Streams en Rust con axum y tokio, soportando lecturas de streaming y productor idempotente","fr":"m13-domain-error est une implémentation de référence de Durable Streams en Rust avec axum et tokio, prenant en charge les lectures de streaming et le producteur idempotent","de":"m13-domain-error ist eine Referenzimplementierung von Durable Streams in Rust mit axum und tokio, unterstützt Streaming-Lesevorgänge und idempotente Produzenten","pt":"Implementação em Rust do protocolo Durable Streams com axum e tokio, suportando leituras de streaming e produtor idempotente","ru":"Реализация на Rust протокола Durable Streams с axum и tokio, поддерживающая потоковые чтения и идемпотентный продюсер","ar":"تنفيذ بروستل للبروتوكول Durable Streams مع axum و tokio، يدعم قراءات التدفق وإنتاج المُتكرر","en":"  Reference implementation of the Durable Streams protocol in Rust, built with axum and tokio. Supports streaming reads (long-poll, SSE), producer idempotency, JSON batch mode, TTL "},"seo":{"title":{"zh":"AI智能代理m13-domain-err