INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThinkEx-OSS/thinkex/primitives', 'primitives', 'ThinkEx-OSS', 'thinkex', 'community', 'primitives ThinkEx-OSS thinkex community primitives 是一种重新思考人机交互界面的 AI 智能代理技术，旨在提升用户体验 primitives は、ユーザーインターフェースを再考した AI エージェント技術で、ユーザーエクスペリエンスを向上させることを目的としています primitives는 사용자 인터페이스를 재정의하는 AI 에이전트 기술로, 사용자 경험을 개선하는 것을 목표로 합니다 Primitives redefine la interfaz de usuario de la inteligencia artificial para desarrolladores, mejorando la interacción y el rendimiento Primitives réinvente l''interface utilisateur de l''intelligence artificielle pour les développeurs, améliorant l''interaction et les performances Primitives gestaltet die Benutzeroberfläche von KI-Tools für Entwickler neu, verbessert die Interaktion und Leistung As primitivas são uma abordagem inovadora para a criação de interfaces de usuário de IA. Aprenda como elas podem melhorar a experiência do usuário Примитивы - это новаторский подход к созданию интерфейсов пользователя ИИ. Узнайте, как они могут улучшить пользовательский опыт البريميتیفز هي مقاربة مبتكرة لإنشاء واجهات المستخدم لآلة الذكاء الاصطناعي. تعلم كيف يمكنها تحسين تجربة المستخدم Rethinking the User Interface of AI AI智能代理 人机交互界面 primitives 使用方法 AI工具比较 React 和 primitives 如何安装 primitives primitives 安装指南 Rethinking the User Interface of AI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Bald0Wang/DeepSeek-Oracle/oracle-actionizer', 'community', 'Bald0Wang', 'DeepSeek-Oracle', 'Bald0Wang/DeepSeek-Oracle', 'oracle-actionizer', 0, 0, 42, '2026-03-04T13:07:01.816Z', '2026-03-04T14:35:52.321Z', '5a62220f3715ce649707e0071171168538a8abf294c42c41969cff6ad13ca9ea', '{"id":"Bald0Wang/DeepSeek-Oracle/oracle-actionizer","name":"oracle-actionizer","description":{"zh":"基于紫微斗数的命理分析系统，使用deepseek等大语言模型进行解读，目前支持姻缘推算","ja":"AIエージェントは、紫微斗数に基づく命理分析システムで、DeepSeekなどの大規模言語モデルを使用して解釈します","ko":"자미두수 기반의 사주 분석 시스템으로 DeepSeek 등의 대규모 언어 모델을 사용하여 해석하며 현재는姻缘 추측을 지원합니다","es":"Oracle Actionizer es un sistema de análisis de destino basado en el modelo de deepseek, que utiliza IA para interpretar el destino y las relaciones","fr":"Oracle Actionizer est un système d''analyse du destin basé sur le modèle de deepseek, qui utilise l''IA pour interpréter le destin et les relations","de":"Oracle Actionizer ist ein Schicksalsanalyse-System basierend auf dem deepseek-Modell, das KI verwendet, um das Schicksal und die Beziehungen zu interpretieren","pt":"O oracle-actionizer é uma ferramenta de IA que realiza análise de destino baseada em astrologia chinesa, utilizando modelos de linguagem avançados","ru":"ИИ агент oracle-actionizer - система анализа судьбы на основе китайской астрологии, использующая продвинутые языковые модели","ar":"أداة الذكاء الاصطناعي oracle-actionizer هي نظام تحليل المصير بالاستناد إلى علم الفلك الصيني، يستخدم نماذج لغة متقدمة","en":"基于紫微斗数的命理分析系统，使用deepseek等大语言模型进行解读。目前是情人节版本，支持姻缘推算。"},"seo":{"title":{"zh":"AIエージェント - 基于紫微斗数的命理分析系统","ja":"AIエージェント - 命理分析システム","ko":"AI 에이전트 - 자미두수 기반의 사주 분석 시스템","es":"Oracle Actionizer: Herramientas de IA para Análisis de De...","fr":"Oracle Actionizer: Outils d''IA pour l''Analyse du Destin","de":"Oracle Actionizer: KI-Tools für Schicksalsanalyse","pt":"Ferramentas de IA: or