INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/claude-code-workflows/coding-principles', 'coding-principles', 'shinpr', 'claude-code-workflows', 'community', 'coding-principles shinpr claude-code-workflows community 基于AI智能代理的生产就绪开发工作流，适用于Claude Code Claude Code用の生産性の高い開発ワークフローをAIエージェントで提供 Claude Code용 생산 준비 개발 워크플로우를 AI 에이전트로 구축 Flujos de trabajo de desarrollo listos para producción con Agentes de IA especializados para Claude Code Flux de travail de développement prêts pour la production avec des Outils d''IA spécialisés pour Claude Code Produktionsbereite Entwicklungswerkflüsse mit spezialisierten KI-Agents für Claude Code Desenvolvimento de fluxos de trabalho prontos para produção com Claude Code, impulsionado por agentes de IA especializados. Готовые к производству потоки разработки с Claude Code, работающие на специализированных ИИ агентах. سلاسل عمل جاهزة للإنتاج مع Claude Code، مدعومة بوكلاء الذكاء الاصطناعي المتخصصين. Production-ready development workflows for Claude Code, powered by specialized AI agents. AI智能代理 coding-principles Claude Code 如何使用AI智能代理 AI智能代理与传统开发工具的区别 AI智能代理安装指南 AI智能代理设置教程 Production-ready development workflows for Claude Code, powered by specialized AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Cyronlee/TransFlow/github-release', 'community', 'Cyronlee', 'TransFlow', 'Cyronlee/TransFlow', 'github-release', 0, 0, 42, '2026-03-04T13:07:01.908Z', '2026-03-04T14:59:52.813Z', '968edf87dd2a922cef2b6f62ab36d822f8138cec224a283e1e894086ecb4c4bd', '{"id":"Cyronlee/TransFlow/github-release","name":"github-release","description":{"zh":"github-release AI工具是一种实时语音转录和翻译工具，支持macOS，完全离线，保护用户隐私","ja":"github-release AIエージェントはリアルタイム音声転写と翻訳ツールであり、macOSに対応、完全オフライン、プライバシー優先","ko":"github-release AI 에이전트는 실시간 음성 인식 및 번역 도구로, macOS 지원, 완전 오프라인, 개인 정보 보호","es":"github-release es una herramienta de transcripción y traducción en tiempo real para macOS, diseñada para ser utilizada sin conexión a Internet y con un enfoque en la privacidad","fr":"github-release est un outil de transcription et de traduction en temps réel pour macOS, conçu pour être utilisé hors ligne et avec un focus sur la vie privée","de":"github-release ist ein Tool für Echtzeit-Transkription und -Übersetzung für macOS, das für den offline-Einsatz konzipiert ist und den Datenschutz in den Vordergrund stellt","pt":"O github-release é uma ferramenta de transcrição e tradução em tempo real para macOS, projetada para ser totalmente offline e priorizar a privacidade","ru":"ИИ Агент github-release - это инструмент для реального времени перевода для macOS, полностью офлайн и с приоритетом приватности","ar":"أداة github-release هي أداة لترجمة النصوص وتحويلها إلى كلام في режим الوقت الحقيقي لمستخدمي ماك، مصممة لتعمل بدون اتصال بالإنترنت وتحافظ على خصوصية المستخدم","en":"Real-time speech transcription & translation for macOS — fully offline, privacy-first"},"seo":{"title":{"zh":"github-release AI工具：实时语音转录和翻译","ja":"github-release AIエージェント：リアルタイム音声転写と翻訳","ko":"github-release AI 에이전트: 실시간 음성 인식 및 번역","es":"Herramientas de AI: github-release para transcripción y t...",