INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('awakecoding/openspecs/windows-protocols', 'windows-protocols', 'awakecoding', 'openspecs', 'community', 'windows-protocols awakecoding openspecs community Microsoft Open Specifications Windows Protocols Skill提供了对Windows协议的深入了解，帮助开发者使用AI智能代理解决方案 Microsoft Open Specifications Windows Protocols Skillは、Windowsプロトコルに関する詳細な情報を提供し、開発者がAIエージェントの解決策を使用できるようにします Microsoft Open Specifications Windows 프로토콜 기술 스킬은 Windows 프로토콜에 대한 심층적인 이해를 제공하며 개발자가 AI 에이전트 솔루션을 사용할 수 있도록 합니다 Aprende sobre los protocolos de Windows de Microsoft Open Specifications y cómo utilizarlos con herramientas de AI para mejorar tus proyectos de desarrollo Apprenez sur les protocoles Windows de Microsoft Open Specifications et comment les utiliser avec des outils d''IA pour améliorer vos projets de développement Erfahren Sie mehr über die Windows-Protokolle von Microsoft Open Specifications und wie Sie diese mit KI-Tools verwenden können, um Ihre Entwicklungsvorhaben zu verbessern As especificações abertas do Windows e os protocolos para desenvolvedores. Aprenda a utilizar as Ferramentas de AI para melhorar a produtividade. Открытые спецификации Windows и протоколы для разработчиков. Узнайте, как использовать ИИ Агенты для повышения производительности. مواصفات ويندوز المفتوحة وبروتوكولاتها لمن-developers. تعرف على كيفية استخدام أدوات الذكاء الاصطناعي لتحسين الإنتاجية. Microsoft Open Specifications Windows Protocols Skill Windows协议 AI智能代理 Microsoft Open Specifications Windows API 如何使用Windows协议 Windows协议开发教程 Windows协议与API的区别 Microsoft Open Specifications Windows Protocols Skill');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cedpaqlab/nexus-php-framework/PHP Framework Development Skills', 'community', 'cedpaqlab', 'nexus-php-framework', 'cedpaqlab/nexus-php-framework', 'PHP Framework Development Skills', 0, 0, 42, '2026-03-01T12:47:24.774Z', '2026-03-01T14:18:38.848Z', '649609b383c7e4c25d78c39aa1a0e41d442b1e30c69baf53ccac511d58722457', '{"id":"cedpaqlab/nexus-php-framework/PHP Framework Development Skills","name":"PHP Framework Development Skills","description":{"zh":"PHP 8.3+ 框架开发技能，包括Propel ORM 2.0、数据库迁移、基于角色的身份验证、CSRF保护和全面的测试套件。一个实验性的AI生成项目","ja":"PHP 8.3+ フレームワーク開発スキルには、Propel ORM 2.0、データベースマイグレーション、ロールベースの認証、CSRF保護、包括的なテストスイートが含まれます。実験的なAI生成プロジェクトです","ko":"PHP 8.3+ 프레임워크 개발 기술은 Propel ORM 2.0, 데이터베이스 마이그레이션, 역할 기반 인증, CSRF 보호 및 포괄적인 테스트 스위트를 포함합니다. 실험적인 AI 생성 프로젝트입니다","es":"Desarrollo de framework PHP 8.3+ con Propel ORM 2.0, migraciones de base de datos y autenticación basada en roles. Proyecto experimental generado por IA","fr":"Développement de framework PHP 8.3+ avec Propel ORM 2.0, migrations de base de données et authentification basée sur les rôles. Projet expérimental généré par IA","de":"Entwicklung von PHP-Framework 8.3+ mit Propel ORM 2.0, Datenbankmigrationen und rollenbasierter Authentifizierung. Experimentelles Projekt generiert von KI","pt":"O projeto de framework PHP 8.3+ apresenta Propel ORM 2.0, migrações de banco de dados e autenticação baseada em papéis","ru":"Проект фреймворка PHP 8.3+ включает Propel ORM 2.0, миграции базы данных и ролевую аутентификацию","ar":"يتضمن مشروع إطار عمل PHP 8.3+ Propel ORM 2.0 وعمليات نقل قاعدة البيانات والتحقق من الهوية المبنية على الأدوار","en":"PHP 8.3+ framework PoC featuring Propel ORM 2.0, database migrations, role-based auth, CSRF protection, and comprehensive test suite. Experimental AI-generated project."},"seo":{"title":{"zh":"AI智能代理：PHP 8.3+ 框架开发技能","ja":"AIエージ